        "Rebar.Loc3row" { return @($lead) + @(
            "Определяет, куда ставить стержень третьего ряда относительно каждого стержня первого ряда.",
            "Stacked: внутрь по радиусу к центру. SideBySide: справа по часовой касательной.",
