        "Steel.*" { return @($lead) + @(
            "Это исходное значение материала обычной ненапрягаемой арматуры в Config. Программа не выполняет автоматическую нормативную проверку соответствия R_s/R_sc/E_s выбранному профилю.",
            "Фактическое напряжение в каждом стержне определяется по диаграмме арматуры выбранного расчета. Тип диаграммы TwoLine/ThreeLine выбирается в отдельной таблице настроек диаграмм.",
