        "SLS.Crack.InitiationLoadPath" { return @($lead) + @(
            "Эта настройка задает, какая часть текущего сочетания масштабируется при поиске момента образования нормальной трещины.",
            "Auto: программа сначала пробует λ*Mxy. Если этот путь не дал расчетную точку образования трещины, пробует λ*N, затем λ*NMxy.",
            "В Auto резервный вариант ψ_s = 1 без найденной точки образования трещины не считается окончательным успехом, пока есть следующий путь. Это помогает получить PreCrackState/PostCrackState там, где другой путь нагрузки это позволяет.",
            "λ*Mxy: продольная сила N остается текущей, а программа увеличивает или уменьшает только моментный вектор Mx/My. Этот путь удобен для изгиба при заданной N.",
            "λ*N: моментный вектор остается текущим, а программа ищет продольную силу N, при которой появляется трещина. Если трещина уже вызвана существующим моментом, отдельную точку по N получить нельзя; тогда программа оставляет ψs = 1.",
            "λ*NMxy: масштабируется весь вектор N/Mx/My. Этот режим полезен, когда нужно найти единый уровень текущего сочетания, при котором появляется нормальная трещина.",
            "Если ручной путь не управляет причиной уже образовавшейся трещины, программа не выдумывает ψ_s,crc: принимается консервативное ψ_s = 1, а в диагностике и Results остается соответствующий статус.",
            "В подробной таблице трещин колонка Method показывает фактически использованный путь. Для ручных режимов он совпадает с настройкой, а для Auto показывает путь, который дал принятую точку.",
            "Эта настройка не выбирает численный метод. Метод задается отдельно в SLS.Crack.InitiationSolutionStrategy."
        ) }
        "SLS.Crack.InitiationSolutionStrategy" { return @($lead) + @(
            "Эта настройка задает, каким численным способом искать уровень образования нормальной трещины на пути SLS.Crack.InitiationLoadPath.",
            "Auto: рекомендуемый режим. Программа сначала пробует прямую предельную постановку UltimateStrain, а если она численно не сошлась, повторяет тот же путь через LoadMultiplier.",
            "UltimateStrain: программа напрямую ищет плоскость деформаций, где нагрузка лежит на выбранной λ-траектории и растянутый бетон достигает ε_bt,ult. Это обычно быстрее, потому что не нужно много раз решать обычное НДС для разных λ.",
            "LoadMultiplier: программа подбирает λ пробными расчетами НДС по модели CrackInitiation. Этот режим медленнее, но может быть устойчивее для сложных или вырожденных траекторий.",
            "Смысл такой же, как у Capacity.SolutionStrategy, но критерий другой: для трещин ищется не разрушение по модели прочности, а достижение предельной растягивающей деформации бетона ε_bt,ult."
        ) }
        "SLS.Crack.Phi1" { return @($lead) + @(
            "Это коэффициент длительности действия нагрузки φ_1 в формуле раскрытия нормальной трещины.",
            "В текущей реализованной схеме программа считает продолжительное раскрытие a_crc = a_crc,1. Для такого расчета обычно принимают φ_1 = 1.4.",
