        "SLS.Crack.PsiMode" { return @($lead) + @(
            "Эта настройка задает только способ принятия коэффициента ψ_s в формуле раскрытия трещины.",
            "Факт образования нормальной трещины программа проверяет всегда до расчета ширины, независимо от режима User, Auto или AlwaysCalc.",
            "User: ψ_s берется из SLS.Crack.PsiS после положительной проверки образования трещины.",
            "Auto: сначала ширина считается с ψ_s = 1. Если полученная ширина a_crc не превышает SLS.Crack.Allowable, уточнение σ_s,crc не требуется.",
            "AlwaysCalc: программа всегда пытается вычислить σ_s,crc по состоянию сразу после образования трещины и применить ψ_s = 1 - 0.8·σ_s,crc/σ_s. Этот режим может дать меньшую ширину, чем Auto, даже если первая проверка с ψ_s = 1 уже проходила.",
            "Если первая проверка Auto не прошла, программа уточняет ψ_s по уже найденному состоянию сразу после образования трещины. В Results доля образования трещины подписана как λ_crc.",
            "Для обычной ветки N + M смысл λ_crc задается настройкой SLS.Crack.InitiationLoadPath: Auto подбирает подходящий путь, а ручные режимы масштабируют только Mxy, только N или весь вектор N/Mx/My.",
            "Трещина считается образованной, когда растянутый бетон достигает предельной деформации ε_bt,ult по СП 63, п. 8.2.14 и 8.1.30.",
            "Для двузначной эпюры принимается ε_bt,ult = ε_bt2. Для однозначно растянутой эпюры с ненулевой кривизной применяется формула (8.54): ε_bt,ult = ε_bt2 - (ε_bt2 - ε_bt0)·ε_1/ε_2. Здесь ε_1 и ε_2 - растягивающие деформации противоположных граней расчетной эпюры.",
            "После нахождения уровня образования трещины программа отдельно считает состояние сразу после ее появления: растянутый бетон уже выключен, а нагрузка соответствует найденному уровню. Из этого состояния берется σ_s,crc по тому же набору стержней, который выбран для текущего сочетания.",
            "σ_s,crc считается как средневзвешенное по площади напряжение этих же стержней: сумма A_s,i·σ_s,i,crc делится на сумму A_s,i. СП 63 задает саму величину σ_s,crc в п. 8.2.18, но не описывает, как усреднять много стержней произвольного сечения N + Mx + My; это принятая НДМ-интерпретация.",
            "Уточнение коэффициента записывается как ψ_s = 1 - 0.8·σ_s,crc·σ_s⁻¹, где σ_s - напряжение той же группы стержней в текущем CrackedState. При численных выбросах значение ограничивается диапазоном 0...1.",
            "Если найденная доля больше 1, нормальная трещина при заданной нагрузке еще не образована, и a_crc принимается равным 0. Текущее CrackedState все равно записывается в Results для проверки продольных трещин и визуального контроля.",
            "Важно: режим растянутого бетона из расчета прочности здесь не используется. Для поиска образования трещины берется модель MaterialModel.CrackInitiation из расчетного профиля. Нормативная настройка для этой стадии: SLS(II), ThreeLine, UseDiagram и кратковременные деформационные параметры.",
            "Базовая формула раскрытия приведена в СП 63.13330.2018, п. 8.2.15, формула (8.128). Для произвольного сечения N + Mx + My программа применяет НДМ-обобщение, потому что СП не дает отдельной пошаговой процедуры для такой дискретной модели."
        ) }
        "SLS.Crack.SigmaSCrcAveragingMode" { return @($lead) + @(
            "Эта настройка влияет только на σ_s,crc - среднее напряжение выбранной арматуры сразу после образования нормальной трещины. Текущее σ_s в основной формуле a_crc считается по текущему CrackedState и по той расчетной группе, которую программа выбрала как растянутую для данного сочетания.",
            "Почему вообще возможны сжатые стержни в σ_s,crc: расчетная группа стержней сначала выбирается по текущему НДС рассматриваемого сочетания. Затем программа смотрит ту же самую группу в другом состоянии - PostCrackState, то есть сразу после образования трещины при нагрузке λ_crc. В этом пороговом состоянии нагрузка меньше или другая по траектории, растянутый бетон уже выключен, и плоскость деформаций может повернуться или сместиться. Поэтому отдельные стержни из ранее выбранной группы могут получить сжимающее напряжение.",
            "AllSelected: программа усредняет напряжения всех выбранных стержней со знаком. Если часть стержней в PostCrackState сжата, эти отрицательные напряжения уменьшают среднее σ_s,crc. Это значение по умолчанию, потому что оно честнее отражает фактическое состояние той же группы стержней сразу после трещинообразования.",
            "TensionOnly: если в PostCrackState выбранный стержень оказался сжатым, его напряжение для среднего σ_s,crc принимается равным 0. При этом площадь этого стержня остается в знаменателе среднего, потому что сама расчетная группа не пересобирается.",
            "Настройка не меняет A_s, d_s,eq, l_s, выбранные стержни и текущее σ_s. Она влияет только на уточнение ψ_s по формуле ψ_s = 1 - 0.8·σ_s,crc/σ_s в режимах SLS.Crack.PsiMode = Auto или AlwaysCalc."
        ) }
        "SLS.Crack.PsiS" { return @($lead) + @(
            "Это пользовательское значение коэффициента ψ_s для режима SLS.Crack.PsiMode = User.",
            "При SLS.Crack.PsiMode = Auto или AlwaysCalc эта ячейка не задает итоговый коэффициент: программа вычисляет ψ_s по принятой автоматической ветке.",
            "Настройка влияет только на формулу ширины раскрытия и не меняет НДС сечения.",
            "Автоматическое уточнение ψ_s выполняется по СП 63.13330.2018, п. 8.2.18, формула (8.137)."
        ) }
        "SLS.Crack.TensionZoneMode" { return @($lead) + @(
            "Эта настройка определяет, какая часть растянутого бетона входит в A_bt для формулы расстояния между трещинами.",
            "FullTension: берется вся фактически растянутая зона бетона. Бетонный конечный элемент попадает в A_bt, если его центр находится в растяжении по найденной плоскости деформаций.",
            "Effective: берется эффективная зона у наиболее растянутой поверхности. Ее глубина принимается h_bt = min(max(x_t; 2a_s); 0.5·h), где x_t - фактическая растянутая зона, a_s - расстояние от оси крайнего растянутого стержня до бетонного контура, h - полный габарит по нормали. Если x_t < 2a_s, для A_bt принимается полоса 2a_s, даже если она заходит за нейтральную линию; бетонные КЭ выбираются по попаданию центра в эту полосу. Стержни для A_s, σ_s и d_s,eq при этом все равно берутся только растянутые.",
            "Геометрия произвольного сечения считается по нормали к нейтральной линии. h - габарит бетона по этой нормали; a_s - расстояние от оси крайнего растянутого стержня до бетонного контура. Точный смысл a_s выбирается настройкой SLS.Crack.CoverDistanceMode.",
            "Внешняя поверхность восстанавливается по прямоугольной оболочке бетонного КЭ. Если источник достоверно знает реальные стороны элемента, используется Rectangle. Если AutoCAD Region имеет надежные A/I, но не является прямоугольником, используется Equivalent rectangle с той же площадью и отношением главных инерций. Если направления по инерциям не определены или инерций нет, используется Equivalent square со стороной √A. Это влияет только на s_t, s_c, h и a_s; реальные A/I остаются расчетными характеристиками элемента.",
            "A_bt считается дискретно: если центр бетонного КЭ попал в расчетную зону, учитывается вся его площадь; частичные площади не считаются. A_s включает только растянутые стержни, оси которых находятся внутри той же зоны.",
            "Расстояние между трещинами: l_{s,0} = 0.5·A_bt·A_s⁻¹·d_s,eq. Затем l_s = max(l_{s,0}; 10·d_s,eq; 100 mm), после этого l_s = min(l_s; 40·d_s,eq; 400 mm). Здесь A_bt - площадь растянутой бетонной зоны, A_s - площадь выбранной растянутой арматуры, d_s,eq - эквивалентный диаметр.",
            "Если в зоне есть разные диаметры, программа использует d_s,eq как отношение двух сумм: числитель Σ(n_i·d_i²), знаменатель Σ(n_i·d_i). Это инженерное дополнение из EN 1992-1-1 для случая, который СП 63 явно не раскрывает.",
            "СП 63.13330.2018, п. 8.2.17 задает формулу (8.136) и ограничения 10d_s...40d_s, 100...400 mm. В программе для этих ограничений d_s принимается как d_s,eq, потому что расчетная группа может содержать стержни разных диаметров. Для произвольного сечения, косого изгиба и дискретной сетки программа применяет описанное выше НДМ-обобщение."
        ) }
        "SLS.Crack.CoverDistanceMode" { return @($lead) + @(
            "Эта настройка уточняет, как программа определяет расстояние a_s от оси крайнего растянутого стержня до бетонного контура.",
            "NearestContour: от оси выбранного стержня проводится луч по нормали к нейтральной линии в сторону растянутой поверхности; a_s принимается до ближайшего выхода из бетонного контура. Этот режим удобен, когда нужно проверить локальное расстояние до ближайшей границы.",
            "GlobalExtreme: a_s считается до дальней растянутой опорной линии всего сечения по той же нормали. Для выступающих или не выпуклых сечений это расстояние может оказаться заметно больше локального.",
            "Найденное a_s используется в режиме Effective для нижнего ограничения глубины эффективной растянутой зоны: h_bt должно быть не меньше 2a_s. Через h_bt выбирается площадь бетона A_bt, затем считается расстояние между трещинами l_s и итоговая ширина a_crc.",
            "Настройка влияет только на расчетную зону A_bt и расстояние между трещинами. Она не меняет найденное НДС, диаграммы материалов, прочность или устойчивость.",
            "Если нейтральной линии нет, например в центральной ветке растяжения, эта настройка не участвует в расчете."
        ) }
        "SLS.Crack.*" { return @($lead) + @(
            "Расчет трещин работает только для сочетаний II группы и использует тот же поиск равновесия, что и остальные состояния. Отдельного специального решателя для трещин нет.",
            "Перед расчетом ширины программа всегда проверяет, образуется ли нормальная трещина при текущей нагрузке. Если трещина не образуется, ширина принимается равной 0, но текущее CrackedState все равно записывается в Results.",
            "При PsiMode = User программа берет пользовательское SLS.Crack.PsiS. При PsiMode = Auto программа сначала считает ширину с ψ_s = 1, а если проверка не проходит, уточняет ψ_s по состоянию сразу после образования трещины. При PsiMode = AlwaysCalc это уточнение применяется всегда, когда доступно состояние сразу после образования трещины.",
            "Путь поиска образования нормальной трещины задается SLS.Crack.InitiationLoadPath: Auto, λ*Mxy, λ*N или λ*NMxy.",
            "Напряжение σ_s определяется напрямую из НДМ по выбранным растянутым стержням как отношение двух сумм: числитель Σ(A_s,i·σ_s,i), знаменатель ΣA_s,i. Здесь σ_s,i берется из диаграммы арматуры для i-го стержня.",
            "Локальные зоны вокруг отдельных стержней и локальный максимум a_crc не реализуются. Используется один глобальный расчет для выбранной растянутой зоны.",
            "Для истинного центрального растяжения применяется отдельная ветка СП 63: если N > N_crc по формуле (8.117), трещина считается образованной; N_crc = A_red·R_bt,ser по формуле (8.127). После образования трещины берется вся площадь бетона и вся продольная растянутая арматура.",
            "Центральное растяжение распознается по нагрузке относительно центра тяжести приведенного сечения, выбранного для расчета N_crc: N должно быть растягивающим, а Mx и My после переноса к этому центру должны быть равны нулю в пределах расчетного допуска.",
            "Load.ReferenceOffset и сдвиг между бетонным и приведенным центром учитываются автоматически. Если после такого переноса появляется момент, расчет идет как внецентренное растяжение по общей ветке N + Mx + My.",
            "В подробной сводке Results есть две зоны: для центрального растяжения выводится N_crc осевой ветки, а для общей ветки N + M выводятся Method, N_crc, M_xy,crc и λ_crc найденной точки. Если соответствующая ветка не применялась или точка не найдена, ключевые ячейки остаются пустыми либо получают N/A.",
            "Принятые ограничения: расчет наклонных трещин, напрягаемой арматуры и непродолжительного раскрытия не реализован."
        ) }
        "AutoCAD.Import.ConcreteLayer" { return @($lead) + @(
            "Импортер просматривает активный чертеж AutoCAD и берет бетонные Region только с этого слоя.",
            "Полилинии, блоки, тексты и объекты на других слоях не участвуют в расчете.",
            "Единицы чертежа считаются миллиметрами. Отдельного коэффициента масштаба импорта сейчас нет, поэтому геометрию в AutoCAD нужно готовить в мм.",
            "Контракт импорта Region: координаты X/Y центра и геометрические размеры всегда трактуются как мм, Area - как мм2, моменты инерции и произведение инерции - как мм4. Это относится и к бетонным, и к арматурным Region.",
            "INPUT/OUTPUT в Config не изменяют трактовку исходных данных AutoCAD. Программа не определяет масштаб по INSUNITS и не переводит чертеж из метров или сантиметров: численные координаты и характеристики должны соответствовать миллиметрам еще до импорта.",
            "Исключение среди настроек импорта - AutoCAD.Import.MinArea: это введенный пользователем порог в INPUT-единице площади, который переводится в мм2. Сама Area Region через INPUT не пересчитывается. При записи геометрии на Results применяется текущий OUTPUT, а единицы сохраняются в заголовках снимка.",
            "Каждый найденный бетонный Region превращается в расчетный бетонный элемент.",
            "Importer читает фактические Area, центр и центральные Ix/Iy/Ixy Region. Он не распознает прямоугольник по BoundingBox и не назначает Width/Height.",
            "Прямоугольную оболочку элемента строит CSectionModel. Rectangle означает, что A/I совместимы с настоящим прямоугольником; Equivalent rectangle - что для границ используется прямоугольник той же площади и того же отношения главных инерций; Equivalent square - что используется квадрат той же площади.",
            "Width, Height и Rotation нужны для границ, h, a_s, схемы и AutoCAD export. В механике, свойствах сечения и устойчивости используются реальные A/I Region; оболочка не подменяет их."
        ) }
        "AutoCAD.Import.RebarLayer" { return @($lead) + @(
