}

# Делает первую строку инструкции одинаково понятной: пользователь сразу видит,
# какой именно ключ открыт и что конкретно он меняет. Остальные строки только
# раскрывают последствия и формулы для этой настройки.
function Get-InstructionLead {
    param([string]$Key, [string]$Comment)

    if ([string]::IsNullOrWhiteSpace($Comment)) {
        return "$Key - настройка Config. Отдельное подробное описание для нее пока не задано."
    }
    return "$Key - $Comment"
}

# Формирует список блоков справки для Config и специальных таблиц настроек.
function Get-SettingsInstructionCatalog {
    $items = New-Object System.Collections.Generic.List[object]
    $items.Add(@{ Key = "Units"; Title = "Единицы измерения"; Lines = @(
        "Этот блок задает пользовательские единицы ввода INPUT и вывода OUTPUT. Колонка INTERNAL является справочной и показывает фиксированные единицы расчетного ядра.",
        "Внутренние единицы ядра: длина - мм, площадь - мм2, сила - Н, момент - Н*мм, напряжение - МПа, кривизна - 1/мм.",
        "Допустимые INPUT/OUTPUT: длина mm, cm, m; площадь mm2, cm2, m2; сила N, kN, tf; момент N*mm, kN*m, tf*m; напряжение Pa, kPa, MPa, kgf/cm2, tf/m2; кривизна 1/mm или 1/m.",
        "Пустой выбор, TODO или неподдержанная единица являются ошибкой Config и не заменяются значением по умолчанию. Сообщение указывает конкретную настройку INPUT или OUTPUT.",
        "Формула: q_internal = q_user · k_input.",
        "Формула: q_output = q_internal·k_output⁻¹.",
        "Все пересчеты единиц выполняются централизованно, поэтому расчетные формулы внутри программы работают в одной системе единиц.",
        "INPUT и OUTPUT могут быть разными. Например нагрузки удобно вводить в tf и tf*m, а результаты смотреть в kN и kN*m.",
        "INPUT-площадь применяется к порогу AutoCAD.Import.MinArea, введенному на Config. Площадь самого AutoCAD Region уже задана в мм2 и через INPUT не масштабируется.",
        "Исключение для геометрического масштаба: экспорт в AutoCAD всегда выполняется в мм независимо от OUTPUT. Геометрия из сохраненного Results приводится обратно к мм перед экспортом; это не меняет единицы напряжений и других расчетных величин в текстовых подписях.",
        "Смена INPUT не пересчитывает уже введенные числа автоматически. Для сохранения того же физического расчета переведите нагрузки, размеры, характеристики материалов и размерные настройки, в том числе допуски solver-а, в новые INPUT-единицы. Смена OUTPUT не меняет внутреннее НДС.",
        "Results является неизменяемым снимком последнего успешного расчета. Если после расчета пользователь поменял OUTPUT units, старые Results и схема не конвертируются заново; новые единицы применятся только после нового расчета.",
        "Импортированная геометрия записывается в Results в выбранных на момент импорта OUTPUT-единицах, которые сохранены в заголовках таблиц. Если затем изменить INPUT или OUTPUT и нажать расчет, программа сначала восстановит геометрию по единицам старого снимка, а новый расчетный снимок запишет уже в текущих OUTPUT-единицах. Повторный импорт из AutoCAD для этого не нужен; сечение не масштабируется заново.",
        "Нагрузки, характеристики материалов и размерные настройки Config не являются импортированной геометрией: их числа читаются в текущих INPUT-единицах. Поэтому смена INPUT без перевода уже введенных чисел меняет их физический смысл, даже когда импортное сечение остается неизменным. Порог AutoCAD.Import.MinArea применяется только при новом импорте и не отфильтровывает заново сохраненный снимок при расчете.",
        "Выбор единиц не является расчетным допущением СП. При корректном обратимом пересчете физический результат должен сохраняться."
    )}) | Out-Null
    $items.Add(@{ Key = "SignConvention"; Title = "Система знаков"; Lines = @(
        "Этот блок задает пользовательскую систему знаков для ввода и вывода N, Mx и My.",
        "Внутри расчетного ядра используется фиксированная INTERNAL convention: растяжение положительное, сжатие отрицательное.",
        "Формула: ε(x, y) = ε_0 + κ_x·y + κ_y·x.",
        "Пользователь может выбрать, считать ли +N сжатием или растяжением. Программа преобразует внешний знак во внутренний перед расчетом и обратно перед записью Results.",
        "Для Mx вариант +Y tension означает положительный момент с растяжением со стороны +Y, а -Y tension меняет внешний знак Mx. Для My аналогично выбираются +X tension и -X tension. Все восемь сочетаний этих трех правил допустимы.",
        "Пустой выбор, TODO или неизвестное правило знаков являются ошибкой Config, а не запросом значения по умолчанию.",
        "Сохраненный Output.SignConvention на Results является описанием сохраненных Results. Он не применяется повторно к N, Mx и My, потому что эти значения уже записаны с конечным пользовательским знаком.",
        "Пользовательские знаки N/Mx/My не меняют знак Stress и Strain: растяжение остается положительным, сжатие отрицательным. KappaX/KappaY описывают плоскость во внутренних осях, поэтому меняется только единица кривизны, но не направление от пользовательского знака момента. Модули усилий, жесткости и положительные расчетные пороги также не получают знаков N/Mx/My.",
        "Цвета схемы определяются не по пользовательскому знаку Stress, а по сохраненному PhysicalState: Compression, Tension, InactiveTensionConcrete или NearZero.",
        "СП 63.13330.2018, п. 8.1.22 задает правило знаков для деформаций и напряжений НДМ: сжатие со знаком минус, растяжение со знаком плюс. Пользовательская настройка знаков меняет только ввод и вывод, а внутренняя математика остается той же."
    )}) | Out-Null
    $items.Add(@{ Key = "LoadCombinations"; Title = "Сочетания нагрузок"; Lines = @(
        "Таблица задает список сочетаний, которые будут рассчитаны при нажатии кнопки Выполнить расчет.",
        "Количество сочетаний определяется количеством строк внутри таблицы. В шаблоне подготовлено 30 строк, но пользователь может добавить или удалить строки; минимально должна остаться одна строка сочетания.",
        "Чтобы добавить сочетание, расширьте именно область rngLoadCombinations: например выделите нижнюю строку таблицы и сдвиньте ее вниз с сохранением пунктирной границы, либо измените адрес диапазона через Формулы -> Диспетчер имен. Не вставляйте целую строку листа, если рядом есть другие таблицы.",
        "На Results между таблицами должны оставаться две чистые строки. Если места не хватает, расчет не начинается; сдвиньте вниз rngStrengthSummaryAnchor, rngCrackSummaryAnchor, rngStabilitySummaryAnchor и/или rngNDMElementResults, а для правых snapshot-блоков при необходимости сдвиньте rngNDMSectionGeometry, rngNDMSectionProperties, rngNDMMaterialDiagrams, rngNDMSectionAnnotations.",
        "CombinationID - короткое имя сочетания. Оно используется в Results, в заголовке схемы, в выборе Plot.LoadCase и AutoCAD.Export.CombinationID.",
        "N, Mx и My вводятся в текущих INPUT-единицах из блока единиц. Пустой Mx или My считается нулем, поэтому одноосный изгиб можно задавать как N + Mx или N + My без заполнения второго момента.",
        "ProfileId задает расчетный профиль из таблицы расчетных профилей. В сочетании пользователь выбирает имя из строки Profile.DisplayName; если это имя переименовать в профилях, выпадающий список обновится. Технические PR1/PR2 остаются внутренними стабильными ID колонок и также принимаются для совместимости.",
        "Профиль определяет только, какие расчеты запрошены и какие материальные модели использовать. Порядок расчета и зависимости между состояниями задает программа, а не строка профиля.",
        "CapacityLoadPath задает, какие компоненты нагрузки масштабируются при поиске несущей способности: Auto, λ*Mx, λ*My, λ*Mxy, λ*N или λ*NMxy. Эта настройка находится в строке сочетания, потому что разные сочетания могут требовать разной траектории поиска.",
        "Внутри программы путь записывается как постоянная часть плюс λ, умноженная на масштабируемую часть: N = N0 + λ·Nbase, Mx = Mx0 + λ·Mxbase, My = My0 + λ·Mybase. Постоянная часть остается без изменения при подборе λ, а Base - это направление, вдоль которого программа увеличивает нагрузку.",
        "Если выбран λ*N, продольная сила N умножается на λ, а момент от ее смещенной линии действия масштабируется вместе с N. Если выбран λ*Mxy, N остается постоянной, а масштабируется только пользовательский вектор моментов.",
        "Если точка приложения силы смещена, момент разделяется на две физические части: пользовательский момент из строки сочетания и момент от продольной силы на плече Load.ReferenceOffset. При λ*N пользовательский момент попадает в Mx0/My0, а момент от силы на плече - в Mxbase/Mybase. Поэтому для моментов постоянная и масштабируемая части могут быть ненулевыми одновременно.",
        "Если CapacityLoadPath = Auto или оставлен пустым, программа сама выбирает понятный вариант: при наличии пользовательского Mx/My используется λ*Mxy, при чистой N - λ*N. Для прозрачности расчетов лучше задавать путь явно.",
        "Comment - пользовательское пояснение к сочетанию. Оно выводится в Summary и добавляется в заголовок схемы в скобках."
    ); Tables = @(
        @{
            Title = "Варианты CapacityLoadPath"
            Headers = @("Вариант", "Что масштабируется", "Что остается постоянным", "Минимально нужно задать", "Недопустимо")
            Rows = @(
                @("Auto", "Программа выбирает путь по ненулевым компонентам строки.", "Зависит от выбранного автоматически пути.", "N <> 0 или Mx/My <> 0.", "Полностью нулевая строка нагрузки."),
                @("λ*Mx", "Пользовательский Mx.", "N, пользовательский My и моменты от эксцентриситета N.", "Mx <> 0.", "Пустой или нулевой Mx."),
                @("λ*My", "Пользовательский My.", "N, пользовательский Mx и моменты от эксцентриситета N.", "My <> 0.", "Пустой или нулевой My."),
                @("λ*Mxy", "Пользовательские Mx и My как один вектор изгиба.", "N и моменты от эксцентриситета N.", "Mx <> 0 или My <> 0.", "Одновременно Mx = 0 и My = 0."),
                @("λ*N", "N и моменты от эксцентриситета этой силы.", "Пользовательские Mx и My.", "N <> 0.", "Пустой или нулевой N."),
                @("λ*NMxy", "Полный внутренний вектор N, Mx, My.", "Ничего: все ненулевые компоненты входят в Base.", "N <> 0 или Mx <> 0 или My <> 0.", "Все масштабируемые компоненты равны нулю.")
            )
        },
        @{
            Title = "Как программа выбирает численный путь"
            Headers = @("Условие", "Что делает программа", "Что видно в Results", "Зачем это сделано", "Комментарий")
            Rows = @(
                @("Capacity.SolutionStrategy = Auto и изгибная траектория λ*Mx/λ*My/λ*Mxy.", "Сначала пробует UltimateStrain; при численной неудаче повторяет тот же CapacityLoadPath через LoadMultiplier.", "CapacitySolutionMethod показывает фактический метод.", "Обычно это самый быстрый путь для предельного момента при заданной N.", "Пользовательский CapacityLoadPath не меняется."),
                @("λ*N или λ*NMxy без пользовательских моментов.", "Использует LoadMultiplier как более устойчивую силовую ветку.", "CapacitySolutionMethod = LoadMultiplier.", "Чистая силовая траектория может быть вырожденной для UltimateStrain на плато диаграммы.", "CapacityLoadPath остается тем, который выбрал пользователь."),
                @("Capacity.SolutionStrategy = LoadMultiplier.", "Сразу выполняет одномерный поиск λ через Capacity.SearchMethod.", "CapacitySolutionMethod = LoadMultiplier.", "Нужен для сложных траекторий и контрольных расчетов.", "Bisection обычно самый предсказуемый, Brent часто быстрее, Secant чувствительнее."),
                @("CapacityLoadPath = Auto или пустой.", "Автоматически выбирает λ*Mxy при наличии Mx/My, иначе λ*N при чистой N.", "В Results выводится фактически принятый CapacityLoadPath.", "Это защита для неполных строк сочетаний.", "Для прозрачности лучше задавать Auto явно."),
                @("Выбрана траектория, но ее масштабируемые компоненты нулевые.", "Возвращает InputErr.", "CapacityStatus = InputErr.", "Нельзя искать множитель для нулевого вектора Base.", "Например λ*Mx при Mx = 0.")
            )
        }
    )}) | Out-Null
    $items.Add(@{ Key = "StabilityLoads"; Title = "Нагрузки для устойчивости"; Lines = @(
        "Эта таблица задает длительную часть нагрузок, которая нужна только для расчета коэффициентов продольного изгиба.",
        "LC должен совпадать с CombinationID из основной таблицы сочетаний. N, Mx и My вводятся в тех же INPUT-единицах и той же системе знаков, что и основные сочетания.",
        "Если вы добавили дополнительные строки в таблицу сочетаний и для них нужна устойчивость, добавьте такие же строки в эту таблицу или расширьте ее через Формулы -> Диспетчер имен.",
        "Для Stability.Code = SP63 пользователь указывает постоянные + длительные нагрузки.",
