            "В табличной ветви e_c ≤ r предельная сила считается по N_ult = φ·(R_b·A_b + R_sc·A_s). Если A_s больше 3% gross-площади бетона A_b, по СП 35 бетонный вклад считается по (A_b - A_s).",
        "Эта поправка относится только к формуле N_ult. Она не заменяет правило (n - 1)A_s для приведенного сечения: через (n - 1)A_s программа определяет центр тяжести, главные оси и ядровое расстояние."
    )}) | Out-Null
    $items.Add(@{ Key = "ConcreteMaterialParameters"; Title = "Параметры бетона"; Lines = @(
        "Пользователь задает исходные сопротивления и модули бетона, а расчетные точки TwoLine/ThreeLine строятся программой автоматически.",
        "Для Strength используется I группа: R_b и R_bt. Для CrackInitiation и CrackedNDS используется II группа: R_b,ser и R_bt,ser.",
