        "Размеры и групповые подписи арматуры создаются по смысловым граням RectSet-сечения и затем сохраняются в Results. Схема не угадывает грани по координатам уже после расчета."
    )}) | Out-Null
    foreach ($section in (Get-SystemSettingsCatalog)) {
        foreach ($row in $section.Rows) {
            $key = [string]$row[0]
            if ($key.Length -gt 0 -and -not $key.StartsWith("[")) {
                $items.Add(@{ Key = $key; Title = $key; Lines = (Get-SettingInstructionLines $key ([string]$row[3])) }) | Out-Null
            }
        }
    }
    foreach ($row in (Get-PlotAnnotationSettingsCatalog)) {
        $key = [string]$row[0]
        $items.Add(@{ Key = $key; Title = "Аннотации схемы: $key"; Lines = (Get-SettingInstructionLines $key ([string]$row[4])) }) | Out-Null
    }
    foreach ($row in (Get-ConcreteMaterialParametersCatalog)) {
        $key = [string]$row[0]
        $items.Add(@{ Key = $key; Title = $key; Lines = (Get-SettingInstructionLines $key ([string]$row[4])) }) | Out-Null
    }
    foreach ($row in (Get-SteelMaterialParametersCatalog)) {
        $key = [string]$row[0]
        $items.Add(@{ Key = $key; Title = $key; Lines = (Get-SettingInstructionLines $key ([string]$row[4])) }) | Out-Null
    }
    foreach ($geometry in (Get-GeometrySettingsCatalog)) {
        if (-not ($geometry.ContainsKey("FaceTable") -and $geometry.FaceTable) -and -not ($geometry.ContainsKey("RoundedRectangleTable") -and $geometry.RoundedRectangleTable) -and -not ($geometry.ContainsKey("HollowRectangleTable") -and $geometry.HollowRectangleTable)) {
            foreach ($row in $geometry.Rows) {
                $key = [string]$row[0]
                if ($key.Length -gt 0 -and $key -notlike "дополнительные*") {
                    $items.Add(@{ Key = $key; Title = $key; Lines = (Get-SettingInstructionLines $key ([string]$row[3])) }) | Out-Null
                }
            }
        }
    }
    $items
}

# Добавляет строку-заголовок в user guide на листе "Справка".
function Add-GuideTitle {
    param([object]$Sheet, [int]$Row, [string]$Text, [int]$FontSize = 13)

    $range = $Sheet.Range($Sheet.Cells.Item($Row, 1), $Sheet.Cells.Item($Row, 6))
    $range.Merge() | Out-Null
    $range.Value2 = $Text
    $range.Font.Bold = $true
    $range.Font.Size = $FontSize
    $range.Interior.Color = 15921906
    $range.HorizontalAlignment = -4131
    return $Row + 1
}

# Разбивает длинный абзац справки на несколько строк.
# Excel плохо подбирает высоту объединенных ячеек при AutoFit, поэтому длинные
# пояснения надежнее хранить несколькими короткими строками, а не одной высокой.
function Split-GuideParagraphText {
    param([string]$Text, [int]$MaxLength = 200)

    $parts = New-Object System.Collections.Generic.List[string]
    $remaining = ([string]$Text).Trim()
    while ($remaining.Length -gt $MaxLength) {
        $breakAt = -1
        foreach ($separator in @(". ", "; ", ": ", ", ", " ")) {
            $candidate = $remaining.LastIndexOf($separator, [Math]::Min($MaxLength, $remaining.Length - 1))
            if ($candidate -gt $breakAt) {
                $breakAt = $candidate + $separator.Length
            }
        }
        if ($breakAt -le 0) {
            $breakAt = $MaxLength
        }

        $parts.Add($remaining.Substring(0, $breakAt).Trim()) | Out-Null
        $remaining = $remaining.Substring($breakAt).Trim()
    }

    if ($remaining.Length -gt 0) {
        $parts.Add($remaining) | Out-Null
    }
    return $parts
}

# Добавляет обычный абзац справки; длинный текст заранее режется на несколько
# строк, чтобы в готовой книге он не обрезался внутри объединенной ячейки.
function Add-GuideParagraph {
    param([object]$Sheet, [int]$Row, [string]$Text)

    $currentRow = $Row
    foreach ($line in (Split-GuideParagraphText $Text)) {
        $range = $Sheet.Range($Sheet.Cells.Item($currentRow, 1), $Sheet.Cells.Item($currentRow, 6))
        $range.Merge() | Out-Null
        $range.Value2 = $line
        $range.WrapText = $true
        $range.VerticalAlignment = -4160
        $currentRow++
    }
    return $currentRow
}

# Удаляет старые картинки формул, созданные прошлой сборкой справки.
# Cells.Clear не трогает Shapes, поэтому без отдельной очистки формулы
# могли бы накапливаться поверх новых строк после повторной пересборки книги.
function Clear-GuideFormulaPictures {
    param([object]$Sheet)

    try {
        for ($i = $Sheet.Shapes.Count; $i -ge 1; $i--) {
            $shape = $Sheet.Shapes.Item($i)
            if ([string]$shape.Name -like "NDMHelpFormula_*") {
                $shape.Delete()
            }
        }
    }
    catch {
        # Если в конкретной версии Excel доступ к Shapes временно недоступен,
        # справка все равно должна собраться; новые формулы будут записаны текстом.
    }
}

# Загружает стандартный .NET-рендеринг формул и подготавливает каталог PNG.
# Картинки надежнее OLE-уравнений при автоматической сборке xlsm, а вручную
# нарисованные дроби выглядят ближе к инженерной записи, чем плоский текст.
function Initialize-FormulaImageRenderer {
    try {
        if (-not (Test-Path -LiteralPath $script:FormulaImageDir)) {
            New-Item -ItemType Directory -Force -Path $script:FormulaImageDir | Out-Null
        }
        Add-Type -AssemblyName System.Drawing -ErrorAction Stop
        return $true
    }
    catch {
        return $false
    }
}

# Создает уникальный путь для очередной формулы. Номер нужен, чтобы Excel
# не переиспользовал кэш картинки при повторной сборке.
function New-FormulaImagePath {
    param([string]$Name)

    $script:FormulaImageCounter++
    $safeName = ($Name -replace "[^\p{L}\p{Nd}_-]+", "_")
    if ([string]::IsNullOrWhiteSpace($safeName)) { $safeName = "formula" }
    return (Join-Path $script:FormulaImageDir ("formula_{0:000}_{1}.png" -f $script:FormulaImageCounter, $safeName))
}

# Создает шрифт для картинки формулы. Cambria Math обычно установлен вместе
# с Office и хорошо отображает греческие символы и индексы; если его нет,
# .NET автоматически подберет доступный fallback.
function New-FormulaFont {
    param([single]$Size, [bool]$Bold = $false)

    $style = [System.Drawing.FontStyle]::Regular
    if ($Bold) { $style = [System.Drawing.FontStyle]::Bold }
    return New-Object System.Drawing.Font("Cambria Math", $Size, $style, [System.Drawing.GraphicsUnit]::Pixel)
}

# Разбирает компактную инженерную запись формулы на фрагменты.
# Символ "_" превращает следующий фрагмент в настоящий нижний индекс,
# а "^" - в верхний индекс. В сам PNG эти служебные символы не попадают.
function ConvertTo-MathRuns {
    param([string]$Text)

    $runs = New-Object System.Collections.Generic.List[object]
    $i = 0
    while ($i -lt $Text.Length) {
        $ch = $Text[$i]
        if ($ch -eq "_" -or $ch -eq "^") {
            $kind = if ($ch -eq "_") { "Sub" } else { "Sup" }
            $i++
            if ($i -ge $Text.Length) { break }

            $script = ""
            if ($Text[$i] -eq "{") {
                $i++
                while ($i -lt $Text.Length -and $Text[$i] -ne "}") {
                    $script += [string]$Text[$i]
                    $i++
                }
                if ($i -lt $Text.Length -and $Text[$i] -eq "}") { $i++ }
            }
            else {
                while ($i -lt $Text.Length) {
                    $c = [string]$Text[$i]
                    if ($c -match "[\p{L}\p{Nd},\.]") {
                        $script += $c
                        $i++
                    }
                    else {
                        break
                    }
                }
            }

            if (-not [string]::IsNullOrWhiteSpace($script)) {
                $runs.Add(@{ Kind = $kind; Text = $script }) | Out-Null
            }
        }
        else {
            $base = ""
            while ($i -lt $Text.Length -and $Text[$i] -ne "_" -and $Text[$i] -ne "^") {
                $base += [string]$Text[$i]
                $i++
            }
            if ($base.Length -gt 0) {
                $runs.Add(@{ Kind = "Base"; Text = $base }) | Out-Null
            }
        }
    }
    return ,$runs
}

# Измеряет формулу с индексами как единую строку. Это нужно, чтобы дроби и
# обычные формулы центрировались по реальной картинке, а не по сырому тексту.
function Measure-MathText {
    param([System.Drawing.Graphics]$Graphics, [string]$Text, [System.Drawing.Font]$BaseFont, [System.Drawing.Font]$ScriptFont)

    $runs = ConvertTo-MathRuns $Text
    $width = 0.0
    $baseSize = $Graphics.MeasureString("Mg", $BaseFont)
    $height = $baseSize.Height * 1.25
    for ($i = 0; $i -lt $runs.Count; $i++) {
        $run = $runs[$i]
        $font = if ($run.Kind -eq "Base") { $BaseFont } else { $ScriptFont }
        $size = $Graphics.MeasureString([string]$run.Text, $font)
        $advance = $size.Width
        # GDI+ MeasureString дает небольшой боковой запас. Для индексов это
        # выглядит как лишний пробел, поэтому поджимаем базовый символ к индексу.
        if ($run.Kind -eq "Base" -and $i + 1 -lt $runs.Count -and $runs[$i + 1].Kind -ne "Base") {
            $advance = [Math]::Max(0, $advance - $ScriptFont.Size * 0.25)
        }
        $width += $advance
    }
    return @{ Width = $width; Height = $height; Runs = $runs; BaseHeight = $baseSize.Height }
}

# Отделяет нормативную приписку от самой формулы. Формула остается крупной,
# а ссылка на СП/EN рисуется меньшим шрифтом, чтобы не спорить с выражением.
function Split-FormulaReference {
    param([string]$Text)

    $match = [regex]::Match($Text, "^(.*?)(\s{2,}(?:СП|EN)\s+.*)$")
    if ($match.Success) {
        return @{
            Formula = $match.Groups[1].Value.TrimEnd()
            Reference = $match.Groups[2].Value.Trim()
        }
    }
    return @{ Formula = $Text; Reference = "" }
}

# Рисует строку формулы с нижними/верхними индексами. Визуально это ближе к
# Excel Equation, но не требует OLE-объектов и не ломается при сборке.
function Draw-MathText {
    param(
        [System.Drawing.Graphics]$Graphics,
        [System.Collections.IEnumerable]$Runs,
        [System.Drawing.Font]$BaseFont,
        [System.Drawing.Font]$ScriptFont,
        [System.Drawing.Brush]$Brush,
        [double]$X,
        [double]$CenterY
    )

    $baseSize = $Graphics.MeasureString("Mg", $BaseFont)
    $scriptSize = $Graphics.MeasureString("Mg", $ScriptFont)
    $baseTop = $CenterY - $baseSize.Height / 2
    $currentX = $X
    $runArray = @($Runs)
    for ($i = 0; $i -lt $runArray.Count; $i++) {
        $run = $runArray[$i]
        if ($run.Kind -eq "Base") {
            $Graphics.DrawString([string]$run.Text, $BaseFont, $Brush, [single]$currentX, [single]$baseTop)
            $advance = $Graphics.MeasureString([string]$run.Text, $BaseFont).Width
            if ($i + 1 -lt $runArray.Count -and $runArray[$i + 1].Kind -ne "Base") {
                $advance = [Math]::Max(0, $advance - $ScriptFont.Size * 0.25)
            }
            $currentX += $advance
        }
        elseif ($run.Kind -eq "Sub") {
            $top = $baseTop + $baseSize.Height * 0.52
            $Graphics.DrawString([string]$run.Text, $ScriptFont, $Brush, [single]$currentX, [single]$top)
            $currentX += $Graphics.MeasureString([string]$run.Text, $ScriptFont).Width
        }
        elseif ($run.Kind -eq "Sup") {
            $top = $baseTop - $scriptSize.Height * 0.2
            $Graphics.DrawString([string]$run.Text, $ScriptFont, $Brush, [single]$currentX, [single]$top)
            $currentX += $Graphics.MeasureString([string]$run.Text, $ScriptFont).Width
        }
    }
    return $currentX - $X
}

# Рисует одну строку формулы в PNG с высоким внутренним разрешением.
function New-TextFormulaImage {
    param([string]$Text)

    if (-not (Initialize-FormulaImageRenderer)) { return $null }

    $font = New-FormulaFont 32
    $scriptFont = New-FormulaFont 21
    $referenceFont = New-FormulaFont 16
    $referenceScriptFont = New-FormulaFont 11
    $paddingX = 24
    $paddingY = 12
    $scale = 2.0
    $referenceGap = 18
    $parts = Split-FormulaReference $Text
    $measureBitmap = New-Object System.Drawing.Bitmap(10, 10)
    $measureGraphics = [System.Drawing.Graphics]::FromImage($measureBitmap)
    $measureGraphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    $math = Measure-MathText $measureGraphics $parts.Formula $font $scriptFont
    $referenceMath = Measure-MathText $measureGraphics $parts.Reference $referenceFont $referenceScriptFont
    $measureGraphics.Dispose()
    $measureBitmap.Dispose()

    $extraGap = if ($referenceMath.Width -gt 0) { $referenceGap } else { 0 }
    $width = [int][Math]::Ceiling($math.Width + $extraGap + $referenceMath.Width + 2 * $paddingX)
    $height = [int][Math]::Ceiling([Math]::Max($math.Height, $referenceMath.Height) + 2 * $paddingY)
    $bitmap = New-Object System.Drawing.Bitmap($width, $height)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    $graphics.Clear([System.Drawing.Color]::FromArgb(250, 250, 252))
    $brush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(30, 30, 30))
    Draw-MathText $graphics $math.Runs $font $scriptFont $brush $paddingX ($height / 2) | Out-Null
    if ($referenceMath.Width -gt 0) {
        Draw-MathText $graphics $referenceMath.Runs $referenceFont $referenceScriptFont $brush ($paddingX + $math.Width + $referenceGap) ($height / 2) | Out-Null
    }

    $path = New-FormulaImagePath "text"
    $bitmap.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
    $graphics.Dispose()
    $brush.Dispose()
    $bitmap.Dispose()
    $font.Dispose()
    $scriptFont.Dispose()
    $referenceFont.Dispose()
    $referenceScriptFont.Dispose()

    return @{ Path = $path; WidthPoints = $width / $scale; HeightPoints = $height / $scale }
}

# Рисует формулу с настоящей горизонтальной дробной чертой.
# Prefix и Suffix остаются обычными частями формулы, а числитель/знаменатель
# центрируются относительно одной дроби.
function New-FractionFormulaImage {
    param(
        [string]$Prefix,
        [string]$Numerator,
        [string]$Denominator,
        [string]$Suffix = ""
    )

    if (-not (Initialize-FormulaImageRenderer)) { return $null }

    $font = New-FormulaFont 32
    $scriptFont = New-FormulaFont 21
    $smallFont = New-FormulaFont 29
    $smallScriptFont = New-FormulaFont 19
    $referenceFont = New-FormulaFont 16
    $referenceScriptFont = New-FormulaFont 11
    $paddingX = 24
    $paddingY = 12
    $scale = 2.0
    $gap = 10
    $lineGap = 5
    $referenceGap = 18
    $suffixParts = Split-FormulaReference $Suffix
    $measureBitmap = New-Object System.Drawing.Bitmap(10, 10)
    $measureGraphics = [System.Drawing.Graphics]::FromImage($measureBitmap)
    $measureGraphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit

    $prefixMath = Measure-MathText $measureGraphics $Prefix $font $scriptFont
    $suffixMath = Measure-MathText $measureGraphics $suffixParts.Formula $font $scriptFont
    $referenceMath = Measure-MathText $measureGraphics $suffixParts.Reference $referenceFont $referenceScriptFont
    $numMath = Measure-MathText $measureGraphics $Numerator $smallFont $smallScriptFont
    $denMath = Measure-MathText $measureGraphics $Denominator $smallFont $smallScriptFont
    $fracWidth = [Math]::Max($numMath.Width, $denMath.Width) + 18
    $fracHeight = $numMath.Height + $denMath.Height + 2 * $lineGap
    $bodyHeight = [Math]::Max([Math]::Max([Math]::Max($prefixMath.Height, $suffixMath.Height), $referenceMath.Height), $fracHeight)
    $extraReferenceGap = if ($referenceMath.Width -gt 0) { $referenceGap } else { 0 }
    $width = [int][Math]::Ceiling($paddingX * 2 + $prefixMath.Width + $gap + $fracWidth + $gap + $suffixMath.Width + $extraReferenceGap + $referenceMath.Width)
    $height = [int][Math]::Ceiling($paddingY * 2 + $bodyHeight)
    $measureGraphics.Dispose()
    $measureBitmap.Dispose()

    $bitmap = New-Object System.Drawing.Bitmap($width, $height)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    $graphics.Clear([System.Drawing.Color]::FromArgb(250, 250, 252))
    $brush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(30, 30, 30))
    $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(30, 30, 30), 2)

    $centerY = $paddingY + $bodyHeight / 2
    $x = $paddingX
    Draw-MathText $graphics $prefixMath.Runs $font $scriptFont $brush $x $centerY | Out-Null
    $x += $prefixMath.Width + $gap

    $fracX = $x
    $lineY = $centerY
    $numX = $fracX + ($fracWidth - $numMath.Width) / 2
    $denX = $fracX + ($fracWidth - $denMath.Width) / 2
    Draw-MathText $graphics $numMath.Runs $smallFont $smallScriptFont $brush $numX ($lineY - $lineGap - $numMath.Height / 2) | Out-Null
    $graphics.DrawLine($pen, $fracX, $lineY, $fracX + $fracWidth, $lineY)
    Draw-MathText $graphics $denMath.Runs $smallFont $smallScriptFont $brush $denX ($lineY + $lineGap + $denMath.Height / 2) | Out-Null
    $x += $fracWidth + $gap

    if (-not [string]::IsNullOrWhiteSpace($suffixParts.Formula)) {
        Draw-MathText $graphics $suffixMath.Runs $font $scriptFont $brush $x $centerY | Out-Null
        $x += $suffixMath.Width
    }
    if ($referenceMath.Width -gt 0) {
        $referenceX = $x
        if ($suffixMath.Width -gt 0) { $referenceX += $referenceGap }
        Draw-MathText $graphics $referenceMath.Runs $referenceFont $referenceScriptFont $brush $referenceX $centerY | Out-Null
    }

    $path = New-FormulaImagePath "fraction"
    $bitmap.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
    $graphics.Dispose()
    $brush.Dispose()
    $pen.Dispose()
    $bitmap.Dispose()
    $font.Dispose()
    $scriptFont.Dispose()
    $smallFont.Dispose()
    $smallScriptFont.Dispose()
    $referenceFont.Dispose()
    $referenceScriptFont.Dispose()

    return @{ Path = $path; WidthPoints = $width / $scale; HeightPoints = $height / $scale }
}

# Рисует составную формулу, где в одной строке может быть несколько настоящих
# дробей. Нужна для методических блоков СП 35/СП 63, где текстовая запись
# вида a/b внутри длинной формулы читается плохо.
function New-CompositeFormulaImage {
    param(
        [object[]]$Segments,
        [string]$Reference = ""
    )

    if (-not (Initialize-FormulaImageRenderer)) { return $null }

    $font = New-FormulaFont 32
    $scriptFont = New-FormulaFont 21
    $smallFont = New-FormulaFont 29
    $smallScriptFont = New-FormulaFont 19
    $referenceFont = New-FormulaFont 16
    $referenceScriptFont = New-FormulaFont 11
    $paddingX = 24
    $paddingY = 12
    $scale = 2.0
    $segmentGap = 2
    $fractionLineGap = 5
    $referenceGap = 18

    $measureBitmap = New-Object System.Drawing.Bitmap(10, 10)
    $measureGraphics = [System.Drawing.Graphics]::FromImage($measureBitmap)
    $measureGraphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit

    $layouts = @()
    $bodyWidth = 0.0
    $bodyHeight = 0.0
    foreach ($segment in $Segments) {
        $kind = [string]($segment["Kind"])
        if ($kind -eq "Fraction") {
            $numMath = Measure-MathText $measureGraphics ([string]$segment["Numerator"]) $smallFont $smallScriptFont
            $denMath = Measure-MathText $measureGraphics ([string]$segment["Denominator"]) $smallFont $smallScriptFont
            $fracWidth = [Math]::Max($numMath.Width, $denMath.Width) + 18
            $fracHeight = $numMath.Height + $denMath.Height + 2 * $fractionLineGap
            $layout = @{
                Kind = "Fraction"
                NumMath = $numMath
                DenMath = $denMath
                Width = $fracWidth
                Height = $fracHeight
            }
        }
        else {
            $textMath = Measure-MathText $measureGraphics ([string]$segment["Text"]) $font $scriptFont
            $layout = @{
                Kind = "Text"
                Math = $textMath
                Width = $textMath.Width
                Height = $textMath.Height
            }
        }
        $layouts += $layout
        $bodyWidth += [double]$layout.Width
        $bodyHeight = [Math]::Max($bodyHeight, [double]$layout.Height)
    }
    if ($layouts.Count -gt 1) { $bodyWidth += $segmentGap * ($layouts.Count - 1) }

    $referenceMath = Measure-MathText $measureGraphics $Reference $referenceFont $referenceScriptFont
    $extraReferenceGap = if ($referenceMath.Width -gt 0) { $referenceGap } else { 0 }
    $width = [int][Math]::Ceiling($paddingX * 2 + $bodyWidth + $extraReferenceGap + $referenceMath.Width)
    $height = [int][Math]::Ceiling($paddingY * 2 + [Math]::Max($bodyHeight, $referenceMath.Height))
    $measureGraphics.Dispose()
    $measureBitmap.Dispose()

    $bitmap = New-Object System.Drawing.Bitmap($width, $height)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    $graphics.Clear([System.Drawing.Color]::FromArgb(250, 250, 252))
    $brush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(30, 30, 30))
    $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(30, 30, 30), 2)

    $centerY = $paddingY + [Math]::Max($bodyHeight, $referenceMath.Height) / 2
    $x = $paddingX
    foreach ($layout in $layouts) {
        if ($layout.Kind -eq "Fraction") {
            $fracX = $x
            $lineY = $centerY
            $numX = $fracX + ($layout.Width - $layout.NumMath.Width) / 2
            $denX = $fracX + ($layout.Width - $layout.DenMath.Width) / 2
            Draw-MathText $graphics $layout.NumMath.Runs $smallFont $smallScriptFont $brush $numX ($lineY - $fractionLineGap - $layout.NumMath.Height / 2) | Out-Null
            $graphics.DrawLine($pen, $fracX, $lineY, $fracX + $layout.Width, $lineY)
            Draw-MathText $graphics $layout.DenMath.Runs $smallFont $smallScriptFont $brush $denX ($lineY + $fractionLineGap + $layout.DenMath.Height / 2) | Out-Null
        }
        else {
            Draw-MathText $graphics $layout.Math.Runs $font $scriptFont $brush $x $centerY | Out-Null
        }
        $x += [double]$layout.Width + $segmentGap
    }
    if ($referenceMath.Width -gt 0) {
        Draw-MathText $graphics $referenceMath.Runs $referenceFont $referenceScriptFont $brush ($paddingX + $bodyWidth + $referenceGap) $centerY | Out-Null
    }

    $path = New-FormulaImagePath "composite"
    $bitmap.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
    $graphics.Dispose()
    $brush.Dispose()
    $pen.Dispose()
    $bitmap.Dispose()
    $font.Dispose()
    $scriptFont.Dispose()
    $smallFont.Dispose()
    $smallScriptFont.Dispose()
    $referenceFont.Dispose()
    $referenceScriptFont.Dispose()

    return @{ Path = $path; WidthPoints = $width / $scale; HeightPoints = $height / $scale }
}

# Делит строку матрицы на ячейки. В исходных строках генератора отдельные
# элементы матрицы разделяются несколькими пробелами, а одинарные пробелы
# остаются внутри выражения, например "N_int - N".
function Split-MatrixFormulaCells {
    param([string]$RowText)

    $cells = @()
    foreach ($cell in ([regex]::Split($RowText.Trim(), "\s{2,}"))) {
        if (-not [string]::IsNullOrWhiteSpace($cell)) {
            $cells += $cell.Trim()
        }
    }
    if ($cells.Count -eq 0 -and -not [string]::IsNullOrWhiteSpace($RowText)) {
        $cells += $RowText.Trim()
    }
    return ,$cells
}

# Измеряет одну ячейку матрицы. Если ячейка записана через "/", она считается
# дробью и дальше рисуется с настоящей горизонтальной чертой.
function Measure-MatrixFormulaCell {
    param(
        [System.Drawing.Graphics]$Graphics,
        [string]$Text,
        [System.Drawing.Font]$Font,
        [System.Drawing.Font]$ScriptFont
    )

    $slashIndex = $Text.IndexOf("/")
    if ($slashIndex -gt 0 -and $slashIndex -lt ($Text.Length - 1) -and $Text.IndexOf("/", $slashIndex + 1) -lt 0) {
        $numerator = $Text.Substring(0, $slashIndex).Trim()
        $denominator = $Text.Substring($slashIndex + 1).Trim()
        if (-not [string]::IsNullOrWhiteSpace($numerator) -and -not [string]::IsNullOrWhiteSpace($denominator)) {
            $numMath = Measure-MathText $Graphics $numerator $Font $ScriptFont
            $denMath = Measure-MathText $Graphics $denominator $Font $ScriptFont
            $lineGap = 5
            return @{
                Kind = "Fraction"
                NumMath = $numMath
                DenMath = $denMath
                LineGap = $lineGap
                Width = [Math]::Max($numMath.Width, $denMath.Width) + 16
                Height = $numMath.Height + $denMath.Height + 2 * $lineGap
            }
        }
    }

    $math = Measure-MathText $Graphics $Text $Font $ScriptFont
    return @{
        Kind = "Text"
        Math = $math
        Width = $math.Width
        Height = $math.Height
    }
}

# Рисует одну уже измеренную ячейку матрицы. Для дроби центрирует числитель
# и знаменатель относительно общей дробной черты.
function Draw-MatrixFormulaCell {
    param(
        [System.Drawing.Graphics]$Graphics,
        [hashtable]$Layout,
        [System.Drawing.Font]$Font,
        [System.Drawing.Font]$ScriptFont,
        [System.Drawing.Brush]$Brush,
        [System.Drawing.Pen]$Pen,
        [double]$X,
        [double]$CenterY
    )

    if ($Layout.Kind -eq "Fraction") {
        $lineY = $CenterY
        $numX = $X + ($Layout.Width - $Layout.NumMath.Width) / 2
        $denX = $X + ($Layout.Width - $Layout.DenMath.Width) / 2
        Draw-MathText $Graphics $Layout.NumMath.Runs $Font $ScriptFont $Brush $numX ($lineY - $Layout.LineGap - $Layout.NumMath.Height / 2) | Out-Null
        $Graphics.DrawLine($Pen, $X, $lineY, $X + $Layout.Width, $lineY)
        Draw-MathText $Graphics $Layout.DenMath.Runs $Font $ScriptFont $Brush $denX ($lineY + $Layout.LineGap + $Layout.DenMath.Height / 2) | Out-Null
        return
    }

    Draw-MathText $Graphics $Layout.Math.Runs $Font $ScriptFont $Brush $X $CenterY | Out-Null
}

# Рисует многострочную векторно-матричную формулу как PNG.
# Строки вида "R = [ ... ]" превращаются в одну матрицу с общей большой
# скобкой, чтобы в справке оставалась инженерная запись, а не псевдотекст.
function New-MatrixFormulaImage {
    param([string[]]$Lines)

    if (-not (Initialize-FormulaImageRenderer)) { return $null }

    $font = New-FormulaFont 32
    $scriptFont = New-FormulaFont 21
    $paddingX = 28
    $paddingY = 16
    $scale = 2.0
    $rowGap = 6
    $prefixGap = 16
    $bracketWidth = 14
    $matrixPad = 14
    $columnGap = 26

    $measureBitmap = New-Object System.Drawing.Bitmap(10, 10)
    $measureGraphics = [System.Drawing.Graphics]::FromImage($measureBitmap)
    $measureGraphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit

    $matrixRows = @()
    $prefixText = ""
    $prefixRow = 0
    $fallbackLines = @()
    for ($i = 0; $i -lt $Lines.Count; $i++) {
        $line = [string]$Lines[$i]
        $leftBracket = $line.IndexOf("[")
        $rightBracket = $line.LastIndexOf("]")
        if ($leftBracket -ge 0 -and $rightBracket -gt $leftBracket) {
            $prefix = $line.Substring(0, $leftBracket).Trim()
            if (-not [string]::IsNullOrWhiteSpace($prefix)) {
                $prefixText = $prefix
                $prefixRow = $i
            }
            $matrixRows += $line.Substring($leftBracket + 1, $rightBracket - $leftBracket - 1).Trim()
        }
        else {
            $fallbackLines += $line
        }
    }

    if ($matrixRows.Count -eq 0 -or $fallbackLines.Count -gt 0) {
        $lineLayouts = @()
        $maxWidth = 0.0
        $lineHeight = 0.0
        foreach ($line in $Lines) {
            $math = Measure-MathText $measureGraphics $line $font $scriptFont
            $lineLayouts += $math
            $maxWidth = [Math]::Max($maxWidth, $math.Width)
            $lineHeight = [Math]::Max($lineHeight, $math.Height)
        }
        $width = [int][Math]::Ceiling($paddingX * 2 + $maxWidth)
        $height = [int][Math]::Ceiling($paddingY * 2 + $lineLayouts.Count * $lineHeight + [Math]::Max(0, $lineLayouts.Count - 1) * $rowGap)
        $measureGraphics.Dispose()
        $measureBitmap.Dispose()

        $bitmap = New-Object System.Drawing.Bitmap($width, $height)
        $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
        $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $graphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
        $graphics.Clear([System.Drawing.Color]::FromArgb(250, 250, 252))
        $brush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(30, 30, 30))

        $y = $paddingY + $lineHeight / 2
        foreach ($layout in $lineLayouts) {
            Draw-MathText $graphics $layout.Runs $font $scriptFont $brush (($width - $layout.Width) / 2) $y | Out-Null
            $y += $lineHeight + $rowGap
        }

        $path = New-FormulaImagePath "matrix"
        $bitmap.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
        $graphics.Dispose()
        $brush.Dispose()
        $bitmap.Dispose()
        $font.Dispose()
        $scriptFont.Dispose()
        return @{ Path = $path; WidthPoints = $width / $scale; HeightPoints = $height / $scale }
    }

    $rowLayouts = @()
    $columnWidths = @()
    $rowHeights = @()
    $maxColumnCount = 0
    foreach ($matrixRow in $matrixRows) {
        $cells = Split-MatrixFormulaCells $matrixRow
        $cellLayouts = @()
        $rowHeight = 0.0
        for ($j = 0; $j -lt $cells.Count; $j++) {
            $cellLayout = Measure-MatrixFormulaCell $measureGraphics $cells[$j] $font $scriptFont
            $cellLayouts += $cellLayout
            $rowHeight = [Math]::Max($rowHeight, [double]$cellLayout.Height)
            if ($columnWidths.Count -le $j) {
                $columnWidths += [double]$cellLayout.Width
            }
            else {
                $columnWidths[$j] = [Math]::Max([double]$columnWidths[$j], [double]$cellLayout.Width)
            }
        }
        $rowLayouts += ,$cellLayouts
        $rowHeights += $rowHeight
        $maxColumnCount = [Math]::Max($maxColumnCount, $cells.Count)
    }
    $prefixMath = Measure-MathText $measureGraphics $prefixText $font $scriptFont
    $prefixWidth = if ([string]::IsNullOrWhiteSpace($prefixText)) { 0.0 } else { $prefixMath.Width + $prefixGap }
    $matrixContentWidth = 0.0
    foreach ($columnWidth in $columnWidths) {
        $matrixContentWidth += [double]$columnWidth
    }
    if ($columnWidths.Count -gt 1) {
        $matrixContentWidth += $columnGap * ($columnWidths.Count - 1)
    }
    $matrixHeight = 0.0
    foreach ($heightValue in $rowHeights) {
        $matrixHeight += [double]$heightValue
    }
    if ($rowHeights.Count -gt 1) {
        $matrixHeight += $rowGap * ($rowHeights.Count - 1)
    }
    $width = [int][Math]::Ceiling($paddingX * 2 + $prefixWidth + $bracketWidth * 2 + $matrixPad * 2 + $matrixContentWidth)
    $height = [int][Math]::Ceiling($paddingY * 2 + $matrixHeight)
    $measureGraphics.Dispose()
    $measureBitmap.Dispose()

    $bitmap = New-Object System.Drawing.Bitmap($width, $height)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
    $graphics.Clear([System.Drawing.Color]::FromArgb(250, 250, 252))
    $brush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(30, 30, 30))
    $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(30, 30, 30), 2)

    $matrixTop = $paddingY
    $matrixBottom = $height - $paddingY
    $matrixLeft = $paddingX + $prefixWidth
    $contentLeft = $matrixLeft + $bracketWidth + $matrixPad
    $rightBracketX = $contentLeft + $matrixContentWidth + $matrixPad

    if (-not [string]::IsNullOrWhiteSpace($prefixText)) {
        $prefixCenterY = $matrixTop
        for ($i = 0; $i -lt $prefixRow; $i++) {
            $prefixCenterY += [double]$rowHeights[$i] + $rowGap
        }
        $prefixCenterY += [double]$rowHeights[$prefixRow] / 2
        Draw-MathText $graphics $prefixMath.Runs $font $scriptFont $brush $paddingX $prefixCenterY | Out-Null
    }

    # Левая и правая квадратные скобки рисуются общей высоты матрицы.
    $graphics.DrawLine($pen, $matrixLeft + $bracketWidth, $matrixTop, $matrixLeft, $matrixTop)
    $graphics.DrawLine($pen, $matrixLeft, $matrixTop, $matrixLeft, $matrixBottom)
    $graphics.DrawLine($pen, $matrixLeft, $matrixBottom, $matrixLeft + $bracketWidth, $matrixBottom)
    $graphics.DrawLine($pen, $rightBracketX, $matrixTop, $rightBracketX + $bracketWidth, $matrixTop)
    $graphics.DrawLine($pen, $rightBracketX + $bracketWidth, $matrixTop, $rightBracketX + $bracketWidth, $matrixBottom)
    $graphics.DrawLine($pen, $rightBracketX + $bracketWidth, $matrixBottom, $rightBracketX, $matrixBottom)

    $yTop = $matrixTop
    for ($i = 0; $i -lt $rowLayouts.Count; $i++) {
        $cellLayouts = $rowLayouts[$i]
        $centerY = $yTop + [double]$rowHeights[$i] / 2
        $x = $contentLeft
        for ($j = 0; $j -lt $cellLayouts.Count; $j++) {
            $cellLayout = $cellLayouts[$j]
            $cellX = $x + ([double]$columnWidths[$j] - [double]$cellLayout.Width) / 2
            Draw-MatrixFormulaCell $graphics $cellLayout $font $scriptFont $brush $pen $cellX $centerY
            $x += [double]$columnWidths[$j] + $columnGap
        }
        $yTop += [double]$rowHeights[$i] + $rowGap
    }

    $path = New-FormulaImagePath "matrix"
    $bitmap.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
    $graphics.Dispose()
    $brush.Dispose()
    $pen.Dispose()
    $bitmap.Dispose()
    $font.Dispose()
    $scriptFont.Dispose()

    return @{ Path = $path; WidthPoints = $width / $scale; HeightPoints = $height / $scale }
}

# Вставляет PNG формулы в объединенную строку справки. Если картинку создать
# не удалось, вызывающий метод заранее оставляет в ячейке текстовую формулу.
function Add-GuideFormulaPicture {
    param([object]$Sheet, [int]$Row, [hashtable]$ImageInfo, [string]$FallbackText)

    $range = $Sheet.Range($Sheet.Cells.Item($Row, 1), $Sheet.Cells.Item($Row, 6))
    $range.Merge() | Out-Null
    $range.Value2 = $FallbackText
    $range.Font.Name = "Arial"
    $range.Font.Size = 12
    $range.Font.Italic = $true
    $range.Interior.Color = 16448250
    $range.HorizontalAlignment = -4108
    $range.VerticalAlignment = -4108

    if ($null -eq $ImageInfo -or -not (Test-Path -LiteralPath $ImageInfo.Path)) {
        return $Row + 1
    }

    $maxWidth = [double]$range.Width - 16
    $width = [double]$ImageInfo.WidthPoints
    $height = [double]$ImageInfo.HeightPoints
    if ($width -gt $maxWidth -and $maxWidth -gt 0) {
        $factor = $maxWidth / $width
        $width *= $factor
        $height *= $factor
    }

    $rowHeight = [Math]::Max(36, $height + 8)
    $Sheet.Rows.Item($Row).RowHeight = $rowHeight
    $range.Value2 = ""

    $left = [double]$range.Left + ([double]$range.Width - $width) / 2
    $top = [double]$range.Top + ($rowHeight - $height) / 2
    $picture = $Sheet.Shapes.AddPicture($ImageInfo.Path, $false, $true, $left, $top, $width, $height)
    $picture.Name = "NDMHelpFormula_" + ("{0:000}" -f $script:FormulaImageCounter)
    # xlMoveAndSize: формула ведет себя как содержимое строки и скрывается вместе с группой справки.
    $picture.Placement = 1
    $script:FormulaImageRows.Add(@{ Row = $Row; Height = $rowHeight }) | Out-Null
    return $Row + 1
}

# Добавляет компактную формулу в отдельном выделенном блоке.
function Add-GuideFormula {
    param([object]$Sheet, [int]$Row, [string]$Text)

    $image = New-TextFormulaImage $Text
    return (Add-GuideFormulaPicture $Sheet $Row $image $Text)
}

# Добавляет многострочный формульный блок для векторно-матричных записей.
# Такие формулы вставляются картинками с общей матричной скобкой, как и остальные
# важные формулы справки, а текст остается только fallback-ом при сбое рендера.
function Add-GuideMatrixFormula {
    param([object]$Sheet, [int]$Row, [string[]]$Lines)

    $fallback = ($Lines -join "`r`n")
    $image = New-MatrixFormulaImage $Lines
    return (Add-GuideFormulaPicture $Sheet $Row $image $fallback)
}

# Рисует ключевую формулу с дробью в виде картинки. Это сохраняет внешний вид
# полноценной инженерной записи и не зависит от OLE Equation Editor.
function Add-GuideFractionFormula {
    param(
        [object]$Sheet,
        [int]$Row,
        [string]$Prefix,
        [string]$Numerator,
        [string]$Denominator,
        [string]$Suffix = ""
    )

    $fallback = ($Prefix + " (" + $Numerator + ") / (" + $Denominator + ") " + $Suffix).Trim()
    $image = New-FractionFormulaImage $Prefix $Numerator $Denominator $Suffix
    return (Add-GuideFormulaPicture $Sheet $Row $image $fallback)
}

# Добавляет составную формулу с несколькими дробями. Fallback остается
# человекочитаемым текстом на случай, если PNG-рендер недоступен.
function Add-GuideCompositeFormula {
    param(
        [object]$Sheet,
        [int]$Row,
        [object[]]$Segments,
        [string]$Reference = "",
        [string]$FallbackText = ""
    )

    if ([string]::IsNullOrWhiteSpace($FallbackText)) {
        $pieces = @()
        foreach ($segment in $Segments) {
            if ([string]($segment["Kind"]) -eq "Fraction") {
                $pieces += "((" + [string]$segment["Numerator"] + ") / (" + [string]$segment["Denominator"] + "))"
            }
            else {
                $pieces += [string]$segment["Text"]
            }
        }
        $FallbackText = ($pieces -join "")
        if (-not [string]::IsNullOrWhiteSpace($Reference)) {
            $FallbackText = $FallbackText + "      " + $Reference
        }
    }

    $image = New-CompositeFormulaImage $Segments $Reference
    return (Add-GuideFormulaPicture $Sheet $Row $image $FallbackText)
}

# Добавляет крупный раздел справки с обычным заголовком и группируемым телом.
# Заголовок остается видимым всегда, а строки тела можно свернуть/развернуть
# стандартным Excel outline.
function Add-CollapsibleGuideSection {
    param(
        [object]$Sheet,
        [int]$StartRow,
        [string]$Title,
        [scriptblock]$BodyBuilder
    )

    $row = Add-GuideTitle $Sheet $StartRow $Title 16
    $bodyStartRow = $row
    $row = & $BodyBuilder $Sheet $row
    $bodyEndRow = $row - 1

    if ($bodyEndRow -ge $bodyStartRow) {
        try {
            $Sheet.Range($Sheet.Cells.Item($bodyStartRow, 1), $Sheet.Cells.Item($bodyEndRow, 1)).EntireRow.Group() | Out-Null
        }
        catch {
            # Если группировка недоступна в конкретном COM-сеансе Excel,
            # сама справка должна остаться читаемой без outline.
        }
    }

    return $row
}

# Формирует методический блок по поиску НДС от текущего сочетания.
# Это описание прямого CSectionSolver: как из заданных N/Mx/My получается
# равновесная плоскость деформаций и какие настройки Config влияют на процесс.
function Add-DirectStateMethodologyGuide {
    param([object]$Sheet, [int]$StartRow)

    $row = $StartRow
    $row = Add-GuideParagraph $Sheet $row "Этот раздел описывает прямой расчет НДС для текущего сочетания. Программа получает заданные N, Mx и My, переносит их в расчетную систему, затем ищет такую плоскость деформаций, при которой внутренние усилия от бетона и арматуры уравновешивают заданную нагрузку."
    $row = Add-GuideParagraph $Sheet $row "Прямой расчет НДС запускается для профиля, где включена строка Calculation.Strength.DirectState. Та же численная схема CSectionSolver используется внутри трещин и LoadMultiplier, но в этом разделе описана именно пользовательская проверка НДС по модели прочности."
    $row++

    $row = Add-GuideTitle $Sheet $row "1. Какие настройки участвуют" 13
    $row = Add-GuideParagraph $Sheet $row "Профиль: прямой расчет НДС выполняется только для тех расчетных профилей, где Calculation.Strength.DirectState = Yes. Если в профиле эта строка выключена, для данного сочетания прямой НДС по модели прочности не запускается."
    $row = Add-GuideParagraph $Sheet $row "Материалы: для этого расчета используются настройки модели прочности: MaterialModel.Strength.ValueSet, MaterialModel.Strength.ConcreteDiagram, MaterialModel.Strength.ConcreteTension и MaterialModel.Strength.SteelDiagram. Иными словами, прямой НДС здесь проверяется именно по расчетной модели прочности, а не по модели трещин или устойчивости."
    $row = Add-GuideParagraph $Sheet $row "Общие настройки решателя: Solver.Method выбирает численный метод: Newton или Secant. Solver.MaxIterations ограничивает число итераций на одной ступени нагрузки, Solver.LoadSteps задает число ступеней приложения нагрузки, а Solver.ToleranceN, Solver.ToleranceMx и Solver.ToleranceMy задают допустимые остаточные невязки по силе и моментам."
    $row = Add-GuideParagraph $Sheet $row "Численные параметры Solver и Capacity должны быть заполнены. Пустая ячейка, TODO, текст вместо числа или ошибка формулы дают InputErr с указанием настройки; значение по умолчанию не подставляется молча. Ноль допустим только там, где разрешен контрактом конкретного параметра. Это правило не относится к необязательным диаметрам дополнительных рядов: пустой диаметр по-прежнему означает отсутствие ряда."
    $row = Add-GuideParagraph $Sheet $row "При ошибке обязательного ввода прочитайте причину в сообщении программы. Если ошибку удалось оформить как результат сочетания, она также выводится в комментарии соответствующего блока Results. При остановке до создания результатов новый расчетный снимок не записывается. Сообщение называет настройку и фактическую ячейку Config, если значение прочитано из таблицы, затем указывает, что исправить: ввести число, выбрать допустимый вариант или исправить формулу. Если строка удалена, адрес не угадывается: указан раздел Config и требуется восстановить строку. Если повреждено имя обязательной таблицы, восстановите ее ссылку в диспетчере имен Excel либо используйте исправный шаблон. Инженерные проверки диапазона могут указывать строку по имени настройки. После исправления снова запустите расчет; ошибочный ввод не считается успешно рассчитанным состоянием."
    $row = Add-GuideParagraph $Sheet $row "Очень большое число может читаться в Excel, но переполняться при переводе INPUT-единиц во внутренние единицы. Для расчетной настройки это ошибка ввода до запуска решателя: уменьшите число в указанной ячейке и проверьте INPUT в таблице единиц Config. Программа не заменяет такое число значением по умолчанию."
    $row = Add-GuideParagraph $Sheet $row "Контроль шага: Solver.LineSearchEnabled, Solver.DampingInitial, Solver.MinLineSearchAlpha, Solver.MaxDeltaEpsilon0 и Solver.MaxDeltaKappa ограничивают слишком резкие изменения плоскости деформаций. Эти настройки применяются и к Newton, и к Secant."
    $row = Add-GuideParagraph $Sheet $row "Secant: Solver.SecantMaxRestarts и Solver.SecantMinStepNorm нужны только для Solver.Method = Secant. Для Newton отдельных специальных настроек сейчас нет: Newton использует общие допуски, ограничения шага и line search."
    $row = Add-GuideParagraph $Sheet $row "DiagramExtension: General.DiagramExtension разрешает численное продолжение активных диаграмм материалов при поиске равновесия. Это может применяться не только к прямому НДС по модели прочности, но и к текущему НДС трещиноватого сечения и к равновесным пробным точкам поисковых алгоритмов. Физические пределы материалов и критерии проверок при этом остаются исходными."
    $row = Add-GuideParagraph $Sheet $row "Отчет и малые моменты: General.ExecutionReportEnabled только включает txt-отчет и не меняет математику. Calculation.ZeroMomentPerDepth применяется до расчета: моменты меньше M_tol = значение·h обнуляются как инженерно ничтожные."
    $row++

    $row = Add-GuideTitle $Sheet $row "2. Подготовка нагрузок" 13
    $row = Add-GuideParagraph $Sheet $row "Строка сочетания читается в пользовательских единицах и знаках. CUnitSystem переводит силу во внутренние Н, моменты в Н*мм, а знак +N приводит к внутренней convention программы. После этого CSectionLoadState переносит моменты от пользовательской точки приложения нагрузки к расчетной системе элементов."
    $row = Add-GuideFormula $Sheet $row "M_x = M_{x,user} + N · (Y_ref - Y_calc)"
    $row = Add-GuideFormula $Sheet $row "M_y = M_{y,user} + N · (X_ref - X_calc)"
    $row = Add-GuideParagraph $Sheet $row "Здесь X_ref/Y_ref - пользовательская точка приложения нагрузки, полученная из Load.ReferenceOffsetX/Y относительно центра тяжести бетонного сечения. X_calc/Y_calc - расчетная точка, к которой на этом этапе переносятся усилия: например центр выбранной расчетной системы или центр, относительно которого solver собирает моменты."
    $row = Add-GuideFormula $Sheet $row "M_tol = Calculation.ZeroMomentPerDepth · h"
    $row = Add-GuideParagraph $Sheet $row "Если |Mx| или |My| меньше своего M_tol, компонент обнуляется. h берется как бетонный габарит в направлении, соответствующем моменту. Этот фильтр нужен, чтобы численный остаток после переносов и поворотов не выбирал неверную ветку расчета."
    $row++

    $row = Add-GuideTitle $Sheet $row "3. Искомая плоскость деформаций" 13
    $row = Add-GuideParagraph $Sheet $row "Неизвестные solver-а - три параметра плоскости деформаций: ε_0, κ_x и κ_y. По ним считается деформация каждого бетонного волокна и каждого стержня."
    $row = Add-GuideFormula $Sheet $row "ε(x, y) = ε_0 + κ_x·y + κ_y·x"
    $row = Add-GuideParagraph $Sheet $row "ε_0 - базовая деформация, κ_x и κ_y - кривизны. x и y - координаты бетонного элемента или оси стержня в расчетной системе координат. Деформация ε безразмерна, кривизны κ_x/κ_y имеют размерность 1/длина."
    $row++

    $row = Add-GuideTitle $Sheet $row "4. Сбор внутренних усилий" 13
    $row = Add-GuideParagraph $Sheet $row "Для каждой пробной плоскости CSectionSolver проходит по всем бетонным и арматурным элементам CSectionModel. Напряжение берется из диаграммы материала по найденной деформации. Для арматуры в бетонной сетке используется добавка steelStress - concreteStress, чтобы не учесть бетон на месте стержня дважды."
    $row = Add-GuideFormula $Sheet $row "N_int = Σ σ_i · A_i"
    $row = Add-GuideFormula $Sheet $row "M_{x,int} = Σ σ_i · A_i · y_i"
    $row = Add-GuideFormula $Sheet $row "M_{y,int} = Σ σ_i · A_i · x_i"
    $row = Add-GuideParagraph $Sheet $row "В этих суммах i - номер бетонного элемента или стержня, σ_i - напряжение в нем, A_i - его расчетная площадь, x_i и y_i - координаты этого элемента. Индекс int означает внутреннее усилие, полученное суммированием по сечению."
    $row = Add-GuideParagraph $Sheet $row "Для обычной оценки состояния достаточно этих трех сумм: они показывают, какие N, Mx и My дает выбранная плоскость деформаций. Такая оценка используется, например, когда плоскость уже известна и нужно только посчитать напряжения, деформации и статус."
    $row = Add-GuideParagraph $Sheet $row "Для Newton нужно дополнительно понять, как изменятся N, Mx и My, если немного изменить ε_0, κ_x или κ_y. Эта зависимость записывается в касательную матрицу. Слово касательная здесь означает, что матрица описывает локальный наклон текущей нелинейной зависимости усилий от параметров плоскости деформаций."
    $row = Add-GuideParagraph $Sheet $row "Касательная матрица собирается по касательным модулям материалов. Касательный модуль - это текущий наклон диаграммы напряжение-деформация в конкретном волокне или стержне. Он нужен Newton-методу, чтобы сделать расчетный шаг сразу в сторону уменьшения невязки равновесия."
    $row++

    $row = Add-GuideTitle $Sheet $row "5. Невязка равновесия" 13
    $row = Add-GuideParagraph $Sheet $row "Цель расчета - сделать внутренние усилия равными заданным. Solver отслеживает три невязки и сравнивает их с пользовательскими допусками."
    $row = Add-GuideMatrixFormula $Sheet $row @(
        "        [ N_int - N     ]",
        "R(u) = [ M_x,int - M_x ]",
        "        [ M_y,int - M_y ]"
    )
    $row = Add-GuideParagraph $Sheet $row "R(u) - вектор невязки равновесия для текущей плоскости деформаций u. Его компоненты R_N, R_Mx и R_My показывают остаток соответственно по продольной силе, моменту Mx и моменту My."
    $row = Add-GuideFormula $Sheet $row "|R_N| ≤ Solver.ToleranceN"
    $row = Add-GuideFormula $Sheet $row "|R_Mx| ≤ Solver.ToleranceMx;     |R_My| ≤ Solver.ToleranceMy"
    $row = Add-GuideParagraph $Sheet $row "Допуски задаются на Config в пользовательских input-единицах, но перед расчетом переводятся во внутренние Н и Н*мм. Поэтому при смене Units.Force.Input или Units.Moment.Input численный смысл допуска сохраняется."
    $row++

    $row = Add-GuideTitle $Sheet $row "6. Newton" 13
    $row = Add-GuideParagraph $Sheet $row "При Solver.Method = Newton программа на каждой итерации заново собирает касательную матрицу K. Эта матрица отвечает на практический вопрос: насколько изменятся внутренние N, Mx и My, если немного изменить ε_0, κ_x или κ_y."
    $row = Add-GuideParagraph $Sheet $row "Если записать невязку равновесия как функцию от плоскости деформаций R(u), то касательная матрица K - это матрица производных этой невязки по трем неизвестным. Строки матрицы соответствуют невязкам по N, Mx и My, а столбцы - параметрам ε_0, κ_x и κ_y."
    $row = Add-GuideMatrixFormula $Sheet $row @(
        "       [ ε_0 ]",
        "u  =   [ κ_x ]",
        "       [ κ_y ]"
    )
    $row = Add-GuideMatrixFormula $Sheet $row @(
        "         [ R_N(u)  ]",
        "R(u) =   [ R_Mx(u) ]",
        "         [ R_My(u) ]"
    )
    $row = Add-GuideMatrixFormula $Sheet $row @(
        "       [ ∂R_N/∂ε_0    ∂R_N/∂κ_x    ∂R_N/∂κ_y  ]",
        "K  =   [ ∂R_Mx/∂ε_0   ∂R_Mx/∂κ_x   ∂R_Mx/∂κ_y ]",
        "       [ ∂R_My/∂ε_0   ∂R_My/∂κ_x   ∂R_My/∂κ_y ]"
    )
    $row = Add-GuideParagraph $Sheet $row "Здесь u - вектор трех неизвестных плоскости деформаций, R(u) - вектор невязки, а K - касательная матрица. Символ ∂ читается как частная производная. Например дробь ∂R_N над ∂ε_0 показывает, как изменится невязка по продольной силе R_N при малом изменении только ε_0, если κ_x и κ_y в этот момент считать неизменными."
    $row = Add-GuideParagraph $Sheet $row "Дальше Newton решает маленькую линейную задачу для поправки Δu. Поправка показывает, как нужно изменить текущую плоскость деформаций, чтобы уменьшить невязку равновесия R."
    $row = Add-GuideFormula $Sheet $row "K · Δu = -R"
    $row = Add-GuideFormula $Sheet $row "u_new = u_old + α · Δu"
    $row = Add-GuideParagraph $Sheet $row "Δu - найденная поправка к ε_0, κ_x и κ_y. u_old - плоскость до итерации, u_new - плоскость после принятого шага. α - множитель line search: при α = 1 принимается полный шаг, при меньшем α шаг дробится."
    $row = Add-GuideParagraph $Sheet $row "Знак минус в правой части означает, что шаг направлен против текущей невязки. Если, например, внутренний момент оказался больше заданного, поправка должна изменить плоскость так, чтобы уменьшить этот избыток."
    $row = Add-GuideParagraph $Sheet $row "Solver.MaxDeltaEpsilon0 и Solver.MaxDeltaKappa ограничивают размер поправки, чтобы расчет не перепрыгивал через важные участки диаграммы материала. Чем меньше эти ограничения, тем осторожнее расчет, но тем больше может быть итераций."
    $row = Add-GuideParagraph $Sheet $row "Если Solver.LineSearchEnabled = Yes, программа не обязана принимать полный шаг сразу. Она пробует множитель α: сначала Solver.DampingInitial, затем уменьшает его до Solver.MinLineSearchAlpha. Шаг принимается, когда новая плоскость деформаций действительно уменьшает невязку."
    $row = Add-GuideParagraph $Sheet $row "Такой line search особенно полезен на кусочно-линейных диаграммах: около изломов касательная матрица может подсказать слишком смелый шаг, а дробление шага делает переход устойчивее."
    $row++

    $row = Add-GuideTitle $Sheet $row "7. Secant" 13
    $row = Add-GuideParagraph $Sheet $row "При Solver.Method = Secant программа не собирает новую касательную матрицу по модулям материалов на каждой итерации. Вместо этого она строит приближенную матрицу чувствительности по предыдущим пробным шагам: как изменилась невязка после уже сделанных изменений ε_0, κ_x и κ_y."
    $row = Add-GuideParagraph $Sheet $row "В коде эта приближенная матрица обозначает ту же идею, что K в Newton, но получается иначе. В начале шага она строится численно: программа немного увеличивает и немного уменьшает каждый параметр плоскости, считает невязку и по разности оценивает один столбец матрицы."
    $row = Add-GuideMatrixFormula $Sheet $row @(
        "        [ ∂R_N/∂ε_0    ∂R_N/∂κ_x    ∂R_N/∂κ_y  ]",
        "B_0 ≈   [ ∂R_Mx/∂ε_0   ∂R_Mx/∂κ_x   ∂R_Mx/∂κ_y ]",
        "        [ ∂R_My/∂ε_0   ∂R_My/∂κ_x   ∂R_My/∂κ_y ]"
    )
    $row = Add-GuideParagraph $Sheet $row "Каждый столбец B_0 программа получает простой численной пробой: чуть увеличивает один параметр плоскости, чуть уменьшает его и смотрит, как изменились три невязки N, Mx и My."
    $row = Add-GuideParagraph $Sheet $row "Индекс j означает номер изменяемого параметра плоскости: j = 1 для ε_0, j = 2 для κ_x, j = 3 для κ_y. Поэтому B_{0,j} - это соответствующий столбец матрицы B_0."
    $row = Add-GuideFractionFormula $Sheet $row "B_{0,j} ≈" "R(u + h_j·e_j) - R(u - h_j·e_j)" "2 · h_j"
    $row = Add-GuideParagraph $Sheet $row "Здесь e_j - единичное изменение только j-го параметра, а h_j - малый численный шаг по этому параметру. Остальные параметры плоскости в этой пробе не меняются."
    $row = Add-GuideParagraph $Sheet $row "После построения B_0 Secant решает такую же по форме линейную задачу, как Newton, но вместо точной касательной матрицы K использует приближенную матрицу B."
    $row = Add-GuideFormula $Sheet $row "B_k · Δu = -R_k"
    $row = Add-GuideFormula $Sheet $row "u_{k+1} = u_k + α · Δu"
    $row = Add-GuideParagraph $Sheet $row "Индекс k означает номер текущей secant-итерации. B_k - приближенная матрица чувствительности на этой итерации, R_k - текущая невязка, u_k и u_{k+1} - плоскости деформаций до и после шага."
    $row = Add-GuideParagraph $Sheet $row "Именно поэтому Secant может быть полезен как альтернативный численный метод: ему не нужна полная текущая касательная матрица. Но за это он платит большей зависимостью от стартовой точки и масштаба нагрузки, потому что приближение строится из истории итераций."
    $row = Add-GuideParagraph $Sheet $row "Когда шаг принят, программа обновляет приближенную матрицу B. Она сравнивает два факта: что матрица B ожидала от сделанного шага и как на самом деле изменилась невязка. По этой разнице матрица немного уточняется для следующей итерации."
    $row = Add-GuideParagraph $Sheet $row "Общие настройки контроля шага и line search для Secant остаются теми же, что для Newton. Если приближенная матрица стала плохой и шаг перестал давать движение, Solver.SecantMaxRestarts разрешает несколько раз перестроить ее заново."
    $row = Add-GuideParagraph $Sheet $row "Solver.SecantMinStepNorm задает минимальный размер secant-шага. Если шаг стал меньше этого порога, программа считает, что расчет застопорился: итерации почти ничего не меняют и продолжать их бессмысленно."
    $row++

    $row = Add-GuideTitle $Sheet $row "8. Ступени нагрузки" 13
    $row = Add-GuideParagraph $Sheet $row "Solver.LoadSteps разбивает приложение нагрузки на несколько ступеней. На первой ступени решается часть полной нагрузки, затем найденная плоскость используется как старт для следующей ступени. Это может помочь при сильно нелинейных состояниях, но увеличивает время."
    $row = Add-GuideParagraph $Sheet $row "В следующей формуле j - номер текущей ступени нагружения: j = 1, 2, ..., Solver.LoadSteps."
    $row = Add-GuideFractionFormula $Sheet $row "F_j =" "F_target · j" "Solver.LoadSteps"
    $row = Add-GuideParagraph $Sheet $row "F_j - нагрузка на j-й ступени, F_target - полная заданная нагрузка сочетания. Под F понимается весь вектор [N, Mx, My]. В обычном режиме Solver.LoadSteps = 1: сразу решается полная нагрузка."
    $row++

    $row = Add-GuideTitle $Sheet $row "9. Стартовые приближения и fallback" 13
    $row = Add-GuideParagraph $Sheet $row "CStateSolutionRunner выбирает стартовую плоскость через CStateGuessBuilder. Для простых случаев используется прямое инженерное приближение. Для опасных или плохо обусловленных случаев программа может попробовать специальный directState-guess по активной плоскости нагрузки."
    $row = Add-GuideParagraph $Sheet $row "Если первое решение не сошлось, runner пробует альтернативное стартовое приближение. Если General.DiagramExtension = Yes, fallback-ветка может решить равновесие на временно продолженной диаграмме материалов. Такой результат показывает, что равновесие математически найдено, но фактическая физическая диаграмма материала уже превышена."
    $row = Add-GuideParagraph $Sheet $row "Для Results это означает FAIL по DirectState, а не OK: состояние найдено только для диагностики и визуализации перегруженного сочетания. Если равновесие не находится даже после fallback-ов, статус становится NumFail."
    $row++

    $row = Add-GuideTitle $Sheet $row "10. Что записывается в Results" 13
    $row = Add-GuideParagraph $Sheet $row "Для успешного прямого НДС Results получает εbc, εbt, εsc, εst, фактические напряжения, высоту сечения h по текущей плоскости, высоту сжатой зоны x, признак использования extension и запас по деформации ε. Все значения выводятся в пользовательских единицах и знаках через CUnitSystem."
    $row = Add-GuideParagraph $Sheet $row "Геометрические характеристики бетонного и приведенного сечения выводятся отдельно в rngNDMSectionProperties. Они не являются результатом одной конкретной нелинейной плоскости деформаций: это справочные характеристики сечения, которые помогают проверять центр тяжести, главные оси, радиусы инерции и ядровые расстояния."
    $row = Add-GuideParagraph $Sheet $row "Если равновесие найдено внутри физической диаграммы, статус DirectState = OK. Если равновесие найдено только с extension или деформации вышли за физические пределы, статус = FAIL. Если solver не смог найти равновесие, статус = NumFail."
    return $row + 2
}

# Формирует методический блок по поиску несущей способности по выбранной
# λ-траектории. Описывает общую постановку, UltimateStrain,
# LoadMultiplier и автоматический выбор фактического метода.
function Add-CapacityMethodologyGuide {
    param([object]$Sheet, [int]$StartRow)

    $row = $StartRow
    $row = Add-GuideParagraph $Sheet $row "Этот раздел описывает поиск предельной несущей способности по выбранной λ-траектории. В отличие от прямого НДС, здесь программа не просто решает заданную нагрузку, а ищет множитель λ, при котором сечение достигает предельного состояния по модели прочности."
    $row = Add-GuideParagraph $Sheet $row "Расчет запускается для профиля, где Calculation.Strength.Capacity = Yes. Геометрия и материалы используются те же, что для модели прочности профиля, но алгоритм выбирает предельную точку по столбцу CapacityLoadPath в строке сочетания."
    $row++

    $row = Add-GuideTitle $Sheet $row "1. Какие настройки участвуют" 13
    $row = Add-GuideParagraph $Sheet $row "Профиль: поиск несущей способности выполняется только для сочетаний, у которых в расчетном профиле включено Calculation.Strength.Capacity = Yes."
    $row = Add-GuideParagraph $Sheet $row "Материалы: используется та же модель прочности, что и для прямого НДС: MaterialModel.Strength.ValueSet, MaterialModel.Strength.ConcreteDiagram, MaterialModel.Strength.ConcreteTension и MaterialModel.Strength.SteelDiagram."
    $row = Add-GuideParagraph $Sheet $row "Путь нагружения: в каждой строке сочетаний столбец CapacityLoadPath задает, что именно увеличивается до предельного состояния: момент, продольная сила или весь вектор N/Mx/My."
    $row = Add-GuideParagraph $Sheet $row "Общие настройки Capacity: Capacity.SolutionStrategy выбирает предпочтительный способ поиска, Capacity.SolverMaxIterations ограничивает число итераций в предельном решателе, а Capacity.ToleranceStrain задает точность попадания в предельную деформацию для UltimateStrain."
    $row = Add-GuideParagraph $Sheet $row "Настройки LoadMultiplier: Capacity.MaxLambda, Capacity.SearchMethod, Capacity.InitialLambda и Capacity.ToleranceLambda относятся к одномерному поиску λ. Capacity.BaseLoadSteps и Capacity.MaxRetries задают, как повторять трудную λ-точку, если равновесие в ней не сошлось с первого раза."
    $row = Add-GuideParagraph $Sheet $row "Связь с Solver: в ветке LoadMultiplier для каждой пробной λ-точки программа снова решает обычное равновесие сечения через CSectionSolver. Поэтому на эту ветку также влияют Solver.Method, допуски Solver.ToleranceN/Mx/My и общие настройки контроля шага Solver."
    $row = Add-GuideParagraph $Sheet $row "DiagramExtension: если General.DiagramExtension = Yes, равновесие отдельной пробной λ-точки может быть найдено на технически продолженной диаграмме. Это нужно только для устойчивости численного поиска. Физический критерий несущей способности все равно проверяется по исходным предельным деформациям материалов."
    $row++

    $row = Add-GuideTitle $Sheet $row "2. Общая λ-траектория" 13
    $row = Add-GuideParagraph $Sheet $row "Все варианты CapacityLoadPath приводятся к одной универсальной записи. Есть постоянная часть нагрузки Offset и масштабируемая часть Base. Программа ищет λ, при котором Target = Offset + λ·Base становится предельной нагрузкой."
    $row = Add-GuideFormula $Sheet $row "N(λ) = N_0 + λ · N_base"
    $row = Add-GuideFormula $Sheet $row "M_x(λ) = M_{x,0} + λ · M_{x,base}"
    $row = Add-GuideFormula $Sheet $row "M_y(λ) = M_{y,0} + λ · M_{y,base}"
    $row = Add-GuideParagraph $Sheet $row "Offset - часть нагрузки, которая остается постоянной при подборе λ. Base - направление увеличения нагрузки: именно эти компоненты умножаются на λ. Подробный список вариантов CapacityLoadPath приведен в справке к таблице сочетаний; здесь важно только то, как программа собирает Offset и Base."
    $row = Add-GuideParagraph $Sheet $row "Перед разложением программа переводит нагрузки в рабочие единицы и знаки, переносит их к расчетной точке через CSectionLoadState и применяет ZeroMoment-фильтр. Затем момент делится на пользовательскую часть и часть от продольной силы на плече."
    $row = Add-GuideFormula $Sheet $row "M_{x,N} = N · Y_{ref}"
    $row = Add-GuideFormula $Sheet $row "M_{y,N} = N · X_{ref}"
    $row = Add-GuideParagraph $Sheet $row "Здесь X_ref и Y_ref - плечи продольной силы относительно расчетной точки. M_{x,u} и M_{y,u} - моменты, которые пользователь ввел в строке сочетания. Дальше действует простое правило: если выбранный путь масштабирует N, то N и момент от нее на плече идут в Base; если N не масштабируется, они остаются в Offset. Пользовательские Mx/My попадают в Base только тогда, когда выбранный путь масштабирует соответствующий момент."
    $row = Add-GuideParagraph $Sheet $row "Поэтому у одного и того же момента могут одновременно появиться постоянная и масштабируемая части: например пользовательский Mx остается постоянным, а добавка Mx от силы N масштабируется вместе с N."
    $row = Add-GuideParagraph $Sheet $row "Короткий пример. Задано N = 100 тс, пользовательские моменты Mx = 50 тс·м и My = 5 тс·м. От смещения точки приложения силы дополнительно получается Mx от N = 10 тс·м и My от N = -3 тс·м."
    $row = Add-GuideParagraph $Sheet $row "Если выбран путь λ*N, постоянными остаются пользовательские моменты, а сила N и моменты от ее плеча масштабируются:"
    $row = Add-GuideFormula $Sheet $row "N(λ) = λ · 100"
    $row = Add-GuideFormula $Sheet $row "M_x(λ) = 50 + λ · 10"
    $row = Add-GuideFormula $Sheet $row "M_y(λ) = 5 - λ · 3"
    $row = Add-GuideParagraph $Sheet $row "Если выбран путь λ*Mxy, сила N и момент от ее плеча остаются постоянными, а пользовательские Mx и My масштабируются:"
    $row = Add-GuideFormula $Sheet $row "N(λ) = 100"
    $row = Add-GuideFormula $Sheet $row "M_x(λ) = 10 + λ · 50"
    $row = Add-GuideFormula $Sheet $row "M_y(λ) = -3 + λ · 5"
    $row = Add-GuideParagraph $Sheet $row "Если выбран путь λ*NMxy, масштабируется весь внутренний вектор сочетания:"
    $row = Add-GuideFormula $Sheet $row "N(λ) = λ · 100"
    $row = Add-GuideFormula $Sheet $row "M_x(λ) = λ · 60"
    $row = Add-GuideFormula $Sheet $row "M_y(λ) = λ · 2"
    $row++

    $row = Add-GuideTitle $Sheet $row "3. Strategy Auto, UltimateStrain и LoadMultiplier" 13
    $row = Add-GuideParagraph $Sheet $row "Capacity.SolutionStrategy = UltimateStrain означает прямой поиск предельной плоскости деформаций. Программа старается сразу найти такое распределение деформаций, при котором нагрузка лежит на выбранной λ-траектории и один из материалов достиг предельной деформации."
    $row = Add-GuideParagraph $Sheet $row "Capacity.SolutionStrategy = LoadMultiplier означает силовой поиск. Программа берет пробное значение λ, получает пробные N/Mx/My и запускает обычный CSectionSolver. Затем λ меняется, пока не будет найдена граница между физически допустимым состоянием и предельным состоянием."
    $row = Add-GuideParagraph $Sheet $row "Capacity.SolutionStrategy = Auto сначала пробует UltimateStrain как более быстрый путь. Если он не дал надежной предельной точки, программа повторяет тот же CapacityLoadPath через LoadMultiplier. В Results всегда выводится фактический Method, который реально сработал."
    $row = Add-GuideParagraph $Sheet $row "Для чисто осевой силовой траектории λ*N, а также для λ*NMxy без пользовательских моментов, программа сразу выбирает LoadMultiplier. Причина в том, что при чистой осевой нагрузке предельная деформация может лежать на почти горизонтальном участке диаграммы, и прямой поиск UltimateStrain становится численно вырожденным: подходящих плоскостей деформаций может быть много, а не одна устойчивая."
    $row++

    $row = Add-GuideTitle $Sheet $row "4. UltimateStrain" 13
    $row = Add-GuideParagraph $Sheet $row "В ветке UltimateStrain неизвестной является не только плоскость деформаций, но и положение этой плоскости на выбранной λ-траектории. Простыми словами: программа ищет, какая предельная эпюра деформаций соответствует именно выбранному направлению увеличения нагрузки."
    $row = Add-GuideParagraph $Sheet $row "Метод одновременно проверяет два требования. Первое: внутренние усилия от найденной плоскости должны соответствовать нагрузке Offset + λ·Base. Второе: хотя бы один контрольный бетонный элемент или стержень должен достичь своей предельной деформации."
    $row = Add-GuideMatrixFormula $Sheet $row @(
        "      [ ε_0 ]",
        "u =   [ κ_x ]",
        "      [ κ_y ]"
    )
    $row = Add-GuideFormula $Sheet $row "Target(u) = Offset + λ(u) · Base"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "max(" },
        @{ Kind = "Fraction"; Numerator = "|ε_b|"; Denominator = "ε_{b,ult}" },
        @{ Kind = "Text"; Text = "; " },
        @{ Kind = "Fraction"; Numerator = "|ε_s|"; Denominator = "ε_{s,ult}" },
        @{ Kind = "Text"; Text = ") = 1" }
    ) "" "max(|ε_b|/ε_{b,ult}; |ε_s|/ε_{s,ult}) = 1"
    $row = Add-GuideParagraph $Sheet $row "u - это три параметра плоскости деформаций. Target(u) - вектор [N, Mx, My], который соответствует найденной плоскости на выбранном LoadPath. λ(u) - множитель нагрузки, который получается из найденной плоскости и выбранного LoadPath."
    $row = Add-GuideParagraph $Sheet $row "В условии предельной деформации ε_b - проверяемая деформация бетона, ε_s - проверяемая деформация арматуры, ε_b,ult и ε_s,ult - соответствующие предельные значения из диаграмм модели прочности. Оператор max означает, что контролируется самый опасный бетонный элемент или стержень."
    $row = Add-GuideParagraph $Sheet $row "Capacity.ToleranceStrain задает, насколько точно нужно попасть в предельную деформацию. Для бетона и арматуры предельные значения берутся из фактических диаграмм модели прочности."
    $row = Add-GuideParagraph $Sheet $row "Capacity.MaxLambda после найденного решения UltimateStrain не обрезает λ. Эта настройка относится только к расширению скобки в LoadMultiplier."
    $row = Add-GuideParagraph $Sheet $row "Если найденная λ некорректна, не конечна, имеет неправильный знак или не соответствует выбранной траектории, UltimateStrain считается численно неуспешным. В режиме Auto после этого запускается LoadMultiplier."
    $row++

    $row = Add-GuideTitle $Sheet $row "5. LoadMultiplier" 13
    $row = Add-GuideParagraph $Sheet $row "LoadMultiplier работает как одномерный поиск по λ. Это означает, что программа меняет только один параметр λ, а все компоненты нагрузки N/Mx/My на каждом шаге вычисляются по выбранной траектории."
    $row = Add-GuideParagraph $Sheet $row "Для каждой пробной λ программа получает целевые N, Mx и My, затем запускает CSectionSolver как обычный прямой расчет НДС. Если равновесие найдено внутри физической диаграммы, эта λ считается допустимой. Если физический предел превышен или равновесие не найдено, эта λ считается верхней или проблемной точкой поиска."
    $row = Add-GuideFormula $Sheet $row "Target(λ_i) = Offset + λ_i · Base"
    $row = Add-GuideParagraph $Sheet $row "λ_i - очередная пробная λ-точка одномерного поиска, i - номер этой пробной точки в процессе расширения интервала или уточнения. Target(λ_i) - фактический вектор нагрузок [N, Mx, My], который передается в CSectionSolver."
    $row = Add-GuideParagraph $Sheet $row "Сначала проверяется λ = 0. Потом программа расширяет верхнюю границу поиска начиная с Capacity.InitialLambda. Расширение продолжается, пока не найдено состояние за физическим пределом или пока λ не достигнет Capacity.MaxLambda."
    $row = Add-GuideParagraph $Sheet $row "Когда нижняя и верхняя границы найдены, программа уточняет λ методом Capacity.SearchMethod. Bisection делит интервал пополам и обычно самый предсказуемый. Brent комбинирует несколько приемов и часто быстрее. Secant использует наклон функции по предыдущим точкам, поэтому может быть быстрее, но чувствительнее к форме зависимости."
    $row = Add-GuideParagraph $Sheet $row "Capacity.ToleranceLambda задает, насколько точно нужно найти λ. Чем меньше допуск, тем точнее результат, но тем больше пробных λ-точек и вызовов CSectionSolver."
    $row++

    $row = Add-GuideTitle $Sheet $row "6. Повторы λ-точек" 13
    $row = Add-GuideParagraph $Sheet $row "Иногда конкретная λ-точка физически нормальная, но численно трудная: прямой расчет НДС в ней может дать NumFail или SingularTangent. В этом случае Capacity.MaxRetries разрешает повторить ту же самую физическую точку более осторожно."
    $row = Add-GuideParagraph $Sheet $row "Важно: при повторе λ, N, Mx и My не меняются. Меняется только способ, которым CSectionSolver подходит к этой точке: больше ступеней нагрузки и меньший допустимый шаг по кривизне."
    $row = Add-GuideFormula $Sheet $row "LoadSteps_eff = Capacity.BaseLoadSteps · 2^{attempt}"
    $row = Add-GuideFractionFormula $Sheet $row "MaxDeltaKappa_eff =" "Solver.MaxDeltaKappa" "2^{attempt}"
    $row = Add-GuideParagraph $Sheet $row "attempt - номер численной попытки для одной и той же λ-точки. attempt 0 - первая попытка с базовыми настройками. attempt 1 - первый повтор: ступеней нагрузки становится вдвое больше, а шаг по кривизне вдвое осторожнее."
    $row = Add-GuideParagraph $Sheet $row "Если Capacity.MaxRetries = 0, выполняется только attempt 0. При MaxRetries = 1 добавляется один повтор. Это не увеличивает время для точек, которые сошлись с первого раза, но помогает отдельным трудным точкам."
    $row++

    $row = Add-GuideTitle $Sheet $row "7. Статус и коэффициент запаса" 13
    $row = Add-GuideParagraph $Sheet $row "Итоговый коэффициент запаса по несущей способности в текущей реализации равен найденному λ_ult. Если λ_ult ≥ 1, заданная нагрузка лежит внутри найденной предельной точки. Если λ_ult < 1, текущая нагрузка уже больше найденной несущей способности."
    $row = Add-GuideFormula $Sheet $row "SF_capacity = λ_ult"
    $row = Add-GuideFormula $Sheet $row "λ_ult ≥ 1  >  проверка проходит"
    $row = Add-GuideFormula $Sheet $row "λ_ult < 1  >  проверка не проходит"
    $row = Add-GuideParagraph $Sheet $row "λ_ult - найденный предельный множитель выбранной траектории. SF_capacity - коэффициент запаса по несущей способности, который попадает в подробный вывод и в rngBatchSummary."
    $row = Add-GuideParagraph $Sheet $row "BaseFail означает, что сечение уже не выдерживает постоянную часть выбранного пути: те усилия, которые остаются при λ = 0. Увеличение масштабируемой нагрузки здесь не начинается. Этот статус появляется только при подтвержденном физическом отказе; сама по себе несходимость равновесия при λ = 0 остается NumFail."
    $row = Add-GuideParagraph $Sheet $row "NumFail означает, что предельная точка не была надежно найдена численно. Это не равнозначно физическому разрушению: нужно смотреть txt-отчет, выбранный путь, настройки LoadMultiplier и прямой НДС."
    $row++

    $row = Add-GuideTitle $Sheet $row "8. Что записывается в Results" 13
    $row = Add-GuideParagraph $Sheet $row "Подробный блок прочности выводит исходную нагрузку, нагрузку относительно центра приведенного сечения, фактические предельные компоненты N_ult, M_x,ult и M_y,ult, предельные деформации, h/x в предельном состоянии, фактический Method и LoadPath."
    $row = Add-GuideParagraph $Sheet $row "Предельные компоненты для пользователя переносятся обратно в точку приложения нагрузки через тот же централизованный класс переноса усилий. Поэтому если пользователь задавал My = 0 в своей точке, компонент My,ult в выводе не должен появляться только из-за внутреннего переноса solver-а."
    $row = Add-GuideParagraph $Sheet $row "Все выходные силы, моменты, напряжения и деформации перед записью проходят CUnitSystem и пользовательскую систему знаков."
    return $row + 2
}

# Формирует верхний методический раздел листа "Справка" по фактическому
# алгоритму расчета нормальных трещин. Подробные настройки ниже остаются
# отдельными блоками, а этот раздел читается как общий user guide.
function Add-CrackWidthMethodologyGuide {
    param([object]$Sheet, [int]$StartRow)

    $row = $StartRow
    $row = Add-GuideParagraph $Sheet $row "Расчет выполняется для нормальных трещин при общем НДС N + Mx + My. Для произвольного сечения программа берет деформации и напряжения из НДМ, а геометрические величины для трещин определяет по нормали к нейтральной линии."
    $row++

    $row = Add-GuideTitle $Sheet $row "1. Условие и формула" 13
    $row = Add-GuideParagraph $Sheet $row "Основное условие принято по СП 63.13330.2018, п. 8.2.6: расчетная ширина нормальной трещины не должна превышать допустимую ширину, заданную пользователем."
    $row = Add-GuideFormula $Sheet $row "a_crc ≤ a_crc,ult      СП 63, п. 8.2.6, ф. (8.118)"
    $row = Add-GuideParagraph $Sheet $row "В текущей версии считается только продолжительное раскрытие для сочетаний II группы. Непродолжительное раскрытие по сумме нескольких состояний в этой версии не реализовано."
    $row = Add-GuideFormula $Sheet $row "a_crc = a_{crc,1}      СП 63, п. 8.2.7, ф. (8.119)"
    $row = Add-GuideFractionFormula $Sheet $row "a_crc = φ_1·φ_2·φ_3·ψ_s ·" "σ_s" "E_s" "· l_s      СП 63, п. 8.2.15, ф. (8.128)"
    $row = Add-GuideParagraph $Sheet $row "a_crc - расчетная ширина раскрытия нормальной трещины, a_crc,1 - продолжительная часть этой ширины, a_crc,ult - допустимая ширина. φ_1, φ_2, φ_3 и ψ_s - коэффициенты формулы СП, σ_s - напряжение растянутой арматуры, E_s - модуль арматуры, l_s - принятое расстояние между трещинами."
    $row = Add-GuideParagraph $Sheet $row "СП 35.13330.2011 в этом блоке используется только для отдельной проверки продольных трещин по сжатому бетону. Она описана после расчета нормальной трещины."
    $row++

    $row = Add-GuideTitle $Sheet $row "2. Сначала проверяется образование трещины" 13
    $row = Add-GuideParagraph $Sheet $row "Для каждого сочетания с включенным Calculation.Crack.Width программа сначала проверяет, появляется ли нормальная трещина при текущей нагрузке. Эта проверка выполняется до расчета ширины раскрытия."
    $row = Add-GuideParagraph $Sheet $row "Если нормальная трещина не образуется, ширина a_crc принимается равной 0. Текущее CrackedState полного сочетания при этом все равно считается и записывается в Results, потому что оно нужно для проверки продольных трещин и для вывода состояния профиля трещин."
    $row = Add-GuideFormula $Sheet $row "λ_crc ≤ 1  >  трещина образуется при текущем сочетании"
    $row = Add-GuideFormula $Sheet $row "λ_crc > 1  >  трещина при текущем сочетании еще не образуется"
    $row = Add-GuideParagraph $Sheet $row "λ_crc показывает уровень, при котором появляется нормальная трещина. При центральном растяжении это доля заданной растягивающей силы N. В общей ветке N + M смысл λ_crc задается настройкой SLS.Crack.InitiationLoadPath: программа может масштабировать только моментный вектор Mx/My, только продольную силу N или весь вектор N/Mx/My. В режиме Auto эти пути пробуются последовательно, а в Results выводится фактически выбранный Method."
    $row++

    $row = Add-GuideTitle $Sheet $row "3. Выбор ветки проверки образования" 13
    $row = Add-GuideParagraph $Sheet $row "Программа проверяет, есть ли чистое центральное растяжение. Проверка выполняется относительно центра тяжести приведенного сечения, который соответствует модели CrackInitiation. Если растягивающая сила действует без моментов относительно этого центра, применяется специальная ветка N_crc. Во всех остальных случаях используется общая ветка образования трещины через нейтральную линию и растянутый бетон."
    $row = Add-GuideParagraph $Sheet $row "Load.ReferenceOffset и сдвиг между бетонным и приведенным центром учитываются централизованно. Поэтому растягивающая N при нулевых пользовательских Mx и My, но с ненулевым смещением точки приложения нагрузки, считается внецентренной и идет по общей ветке."
    $row++

    $row = Add-GuideTitle $Sheet $row "4. Центральное растяжение: N_crc" 13
    $row = Add-GuideParagraph $Sheet $row "Если задано растягивающее N и моментный вектор относительно центра тяжести приведенного сечения равен нулю, включается отдельная ветка центрального растяжения. В этой ветке нейтральная линия отсутствует."
    $row = Add-GuideFormula $Sheet $row "N > N_crc      СП 63, п. 8.2.4, ф. (8.117)"
    $row = Add-GuideParagraph $Sheet $row "СП 63 для центрально-растянутых элементов задает отдельное условие образования трещин через продольную растягивающую силу: если внешнее растягивающее N больше N_crc, нужно выполнять расчет раскрытия трещин."
    $row = Add-GuideFormula $Sheet $row "N_crc = A_red · R_bt,ser      СП 63, п. 8.2.13, ф. (8.127)"
    $row = Add-GuideFractionFormula $Sheet $row "λ_crc =" "N_crc" "N" ""
    $row = Add-GuideParagraph $Sheet $row "N_crc - продольная сила образования трещин при центральном растяжении. A_red - приведенная площадь сечения. R_bt,ser - сопротивление бетона растяжению для II группы предельных состояний."
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "A_red = A_b + A_s,total · " },
        @{ Kind = "Fraction"; Numerator = "E_s"; Denominator = "E_b" }
    ) "" "A_red = A_b + A_s,total · E_s/E_b"
    $row = Add-GuideParagraph $Sheet $row "В формуле A_red величина A_b означает всю площадь бетона, а A_s,total - всю площадь продольной арматуры. Отношение E_s/E_b учитывает приведение арматуры к бетону."
    $row = Add-GuideParagraph $Sheet $row "Если λ_crc > 1, заданная растягивающая сила меньше силы образования трещин. Если λ_crc ≤ 1, трещина считается образованной; дальше берется вся площадь бетона A_bt = A_b и вся растянутая продольная арматура A_s."
    $row++

    $row = Add-GuideTitle $Sheet $row "5. Общая ветка N+M: нейтральная линия и ε_bt,ult" 13
    $row = Add-GuideParagraph $Sheet $row "Во всех нецентральных случаях программа ищет уровень нагрузки, при котором растянутый бетон достигает предельной деформации. Какая часть текущего сочетания масштабируется, задается SLS.Crack.InitiationLoadPath: Auto сначала пробует λ*Mxy, затем λ*N и затем λ*NMxy; λ*Mxy сохраняет текущую N и масштабирует только моментный вектор; λ*N сохраняет текущие моменты и масштабирует только N; λ*NMxy масштабирует весь вектор N/Mx/My."
    $row = Add-GuideParagraph $Sheet $row "Как именно искать этот уровень, задает SLS.Crack.InitiationSolutionStrategy. В режиме UltimateStrain программа напрямую ищет плоскость деформаций по условию ε_bt = ε_bt,ult. В режиме LoadMultiplier программа перебирает λ и для каждой λ-точки решает обычное НДС. В режиме Auto сначала пробуется UltimateStrain, а при численной неудаче тот же путь повторяется через LoadMultiplier."
    $row = Add-GuideParagraph $Sheet $row "В Results для этой общей ветки выводятся N_crc и M_xy,crc в найденной точке образования трещины. Это не отдельный пользовательский расчет, а служебный, но выводимый этап проверки факта образования нормальной трещины."
    $row = Add-GuideParagraph $Sheet $row "Если General.DiagramExtension = Yes, равновесие пробной точки образования трещины может считаться на технически продолженной диаграмме, но само условие образования трещины всегда проверяется по физическому ε_bt,ult. Продолжение диаграммы не увеличивает M_crc/N_crc и не заменяет физический критерий."
    $row = Add-GuideParagraph $Sheet $row "Если эпюра двузначная, то есть в сечении есть и сжатие, и растяжение, СП 63 принимает предельную растягивающую деформацию равной εbt2."
    $row = Add-GuideFormula $Sheet $row "ε_{bt,ult} = ε_{bt2}      СП 63, п. 8.2.14 и 8.1.30"
    $row = Add-GuideParagraph $Sheet $row "Если эпюра однозначно растянутая и кривизна не равна нулю, предельная деформация определяется по формуле (8.54). В ней ε1 и ε2 - растягивающие деформации противоположных граней расчетной эпюры."
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "ε_{bt,ult} = ε_{bt2} - (ε_{bt2} - ε_{bt0}) · " },
        @{ Kind = "Fraction"; Numerator = "ε_1"; Denominator = "ε_2" }
    ) "СП 63, п. 8.1.30, ф. (8.54)" "ε_{bt,ult} = ε_{bt2} - (ε_{bt2} - ε_{bt0}) · ε_1/ε_2      СП 63, п. 8.1.30, ф. (8.54)"
    $row = Add-GuideParagraph $Sheet $row "ε_bt,ult - предельная растягивающая деформация бетона для проверки образования трещины. ε_bt2 и ε_bt0 берутся из диаграммы бетона выбранной модели CrackInitiation. ε1 и ε2 - растягивающие деформации противоположных граней расчетной эпюры в однозначно растянутом состоянии."
    $row = Add-GuideParagraph $Sheet $row "После нахождения уровня образования трещины состояние с работающим растянутым бетоном сохраняется как PreCrackState. Затем программа отдельно решает состояние сразу после образования трещины без работы растянутого бетона; оно сохраняется как PostCrackState."
    $row = Add-GuideParagraph $Sheet $row "Для общей ветки программа строит нормаль к нейтральной линии по найденным κ_x и κ_y. Все расстояния для трещин считаются вдоль этой нормали, направленной в сторону растяжения."
    $row = Add-GuideFormula $Sheet $row "ε(x, y) = ε_0 + κ_x·y + κ_y·x"
    $row = Add-GuideParagraph $Sheet $row "В этой формуле ε(x,y) - относительная деформация точки с координатами x и y. ε_0 - деформация в начале принятой внутренней системы координат."
    $row = Add-GuideParagraph $Sheet $row "κ_x задает изменение деформации по координате y, а κ_y - по координате x. Координаты, ε_0 и кривизны берутся из сохраненного расчетного состояния Results."
    $row = Add-GuideFractionFormula $Sheet $row "n =" "(κ_y, κ_x)" "√(κ_x^2 + κ_y^2)"
    $row = Add-GuideFormula $Sheet $row "s = n_x·x + n_y·y"
    $row = Add-GuideParagraph $Sheet $row "n - единичный вектор нормали к нейтральной линии, направленный в сторону растяжения. n_x и n_y - его проекции на оси X и Y."
    $row = Add-GuideParagraph $Sheet $row "s - координата точки вдоль этой нормали. Чем больше s, тем ближе точка к растянутому краю."
    $row = Add-GuideParagraph $Sheet $row "Даже если нейтральная линия находится за пределами сечения, используется тот же алгоритм: по координате s определяется растянутый край, сжатый край, h, a_s и зона A_bt."
    $row++

    $row = Add-GuideTitle $Sheet $row "6. Текущее CrackedState для ψ_s и продольных трещин" 13
    $row = Add-GuideParagraph $Sheet $row "Для каждого сочетания с включенным Calculation.Crack.Width batch отдельно решает текущее CrackedState для полного заданного сочетания. Это состояние записывается в Results независимо от того, образовалась ли нормальная трещина."
    $row = Add-GuideParagraph $Sheet $row "Если нормальная трещина образовалась, из CrackedState берутся деформации и напряжения арматуры для ψ_s в формуле раскрытия. Если нормальная трещина не образовалась, a_crc остается равной 0, но CrackedState все равно используется для проверки продольных трещин по сжатому бетону."
    $row = Add-GuideParagraph $Sheet $row "Модель CrackedState задается в расчетном профиле. Для нормативной проверки трещин обычно применяют характеристики II группы и сечение с трещиной без работы растянутого бетона; программа использует фактически выбранную пользователем модель."
    $row = Add-GuideParagraph $Sheet $row "СП 63.13330.2018, п. 8.1.23 и 8.1.25 задают общий НДМ-подход; применение тех же данных для произвольного N + Mx + My в расчете трещин является принятой реализацией общей НДМ-постановки."
    $row++

    $row = Add-GuideTitle $Sheet $row "7. Расстояние между трещинами l_s" 13
    $row = Add-GuideParagraph $Sheet $row "Следующий шаг после выбора направления растянутой зоны - определить расстояние между нормальными трещинами. Именно здесь впервые нужны A_bt, A_s и d_s,eq."
    $row = Add-GuideParagraph $Sheet $row "Базовое расстояние между нормальными трещинами считается по СП 63.13330.2018, п. 8.2.17, формула (8.136)."
    $row = Add-GuideFractionFormula $Sheet $row "l_{s,0} = 0.5 ·" "A_bt" "A_s" "· d_s,eq      СП 63, п. 8.2.17, ф. (8.136)"
    $row = Add-GuideFormula $Sheet $row "l_s = max(l_{s,0}; 10·d_s,eq; 100 мм)      СП 63, п. 8.2.17"
    $row = Add-GuideFormula $Sheet $row "l_s = min(l_s; 40·d_s,eq; 400 мм)      СП 63, п. 8.2.17"
    $row = Add-GuideParagraph $Sheet $row "l_{s,0} - расстояние между трещинами до применения нормативных ограничений. l_s - принятое расстояние после нижних и верхних ограничений."
    $row = Add-GuideParagraph $Sheet $row "A_bt - площадь бетона принятой растянутой зоны. A_s - площадь выбранной растянутой арматуры. d_s в ограничениях принимается как d_s,eq."
    $row = Add-GuideParagraph $Sheet $row "Если несколько ограничений действуют одновременно, сначала применяется нижняя граница, затем верхняя. В Results отдельно выводятся l_{s,0} до ограничений и окончательно принятое l_s."
    $row = Add-GuideParagraph $Sheet $row "Дальше по порядку расшифрованы все величины из этой формулы: бетонная зона и внешний контур, расстояние a_s, выбранная арматура и эквивалентный диаметр."
    $row++

    $row = Add-GuideTitle $Sheet $row "8. A_bt: внешняя поверхность бетонных элементов" 13
    $row = Add-GuideParagraph $Sheet $row "Для восстановления внешнего края программа использует прямоугольную оболочку каждого бетонного КЭ. Реальные Area и Ix/Iy/Ixy при этом остаются расчетными характеристиками Region и не пересчитываются из оболочки."
    $row = Add-GuideParagraph $Sheet $row "Если источник достоверно знает стороны элемента, оболочка получает статус Rectangle. Если элемент неизотропный, но его A/I не совпадают с настоящим прямоугольником, строится Equivalent rectangle: он сохраняет площадь и отношение главных инерций. Если главные инерции почти равны или инерций нет, используется Equivalent square со стороной √A; для импортированных квадратных ячеек угол берется по простой прямой грани AutoCAD Region."
    $row = Add-GuideFormula $Sheet $row "b_eq = h_eq = √A"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "h_eq = √A · (" },
        @{ Kind = "Fraction"; Numerator = "I_1"; Denominator = "I_2" },
        @{ Kind = "Text"; Text = ")^{1/4},    b_eq = √A · (" },
        @{ Kind = "Fraction"; Numerator = "I_2"; Denominator = "I_1" },
        @{ Kind = "Text"; Text = ")^{1/4}" }
    ) "" "h_eq = √A · (I_1/I_2)^{1/4}, b_eq = √A · (I_2/I_1)^{1/4}"
    $row = Add-GuideFormula $Sheet $row "h = s_t - s_c"
    $row = Add-GuideParagraph $Sheet $row "A - реальная площадь бетонного элемента, I_1 и I_2 - его главные локальные моменты инерции, b_eq и h_eq - стороны прямоугольной оболочки, которая нужна только для границ и расстояний. Для Equivalent square обе стороны равны √A."
    $row = Add-GuideParagraph $Sheet $row "s_t - координата внешнего наиболее растянутого бетонного края по нормали n. s_c - координата внешнего наиболее сжатого края. Разность h = s_t - s_c дает высоту сечения по нормали к нейтральной линии."
    $row = Add-GuideParagraph $Sheet $row "Эта логика нужна для произвольной дискретной сетки и импортированной AutoCAD-геометрии. Она используется только для геометрических расстояний, высот, границ зон, схемы и AutoCAD export; расчетные усилия НДМ и свойства сечения используют реальные Area и Ix/Iy/Ixy."
    $row++

    $row = Add-GuideTitle $Sheet $row "9. A_bt: расстояние a_s и расчетная зона" 13
    $row = Add-GuideParagraph $Sheet $row "a_s измеряется по нормали к нейтральной линии от оси крайнего растянутого стержня до бетонного контура. Настройка SLS.Crack.CoverDistanceMode задает, какой именно контур считать расчетным."
    $row = Add-GuideParagraph $Sheet $row "NearestContour: программа идет от оси стержня по нормали в сторону растянутой поверхности и берет ближайший выход из бетонного контура. Этот режим удобен, когда нужно проверить локальное расстояние до ближайшей границы."
    $row = Add-GuideParagraph $Sheet $row "GlobalExtreme: программа берет расстояние от оси стержня до дальней растянутой опорной линии всего сечения. Для ступенчатого или не выпуклого сечения это расстояние может быть намного больше локального."
    $row = Add-GuideFormula $Sheet $row "a_s = t_exit  (NearestContour)"
    $row = Add-GuideFormula $Sheet $row "a_s = s_t - s_bar,max  (GlobalExtreme)"
    $row = Add-GuideParagraph $Sheet $row "s_bar,max - максимальная координата оси растянутого стержня по нормали n. s_t - координата дальней растянутой опорной линии всего бетонного сечения. t_exit - расстояние от оси стержня до ближайшего выхода луча из бетонного контура."
    $row = Add-GuideParagraph $Sheet $row "Найденное a_s нужно не само по себе: оно задает минимальную глубину эффективной бетонной зоны 2a_s. Эта зона дает площадь A_bt, а A_bt участвует в расстоянии между трещинами l_s. Поэтому изменение SLS.Crack.CoverDistanceMode может заметно изменить a_crc, особенно для Г-сечений и импортированных несимметричных сеток."
    $row = Add-GuideParagraph $Sheet $row "Если арматура имеет несколько диаметров или рядов, выбирается именно крайний растянутый стержень из принятой расчетной группы."
    $row = Add-GuideParagraph $Sheet $row "SLS.Crack.TensionZoneMode = FullTension берет всю фактически растянутую зону. SLS.Crack.TensionZoneMode = Effective берет эффективную зону по логике п. 8.2.17 СП 63: ограничения 2a_s и 0.5h применяются вместе. Если фактическая растянутая зона меньше 2a_s, расчетная полоса может геометрически зайти за нейтральную линию; бетонные КЭ внутри этой полосы учитываются в A_bt по положению центра."
    $row = Add-GuideFormula $Sheet $row "h_bt = min(max(x_t; 2a_s); 0.5·h)"
    $row = Add-GuideParagraph $Sheet $row "h_bt - глубина эффективной зоны, а x_t - фактическая высота растянутой зоны до нейтральной линии. h - полный габарит сечения по нормали."
    $row = Add-GuideParagraph $Sheet $row "В режиме Effective бетонный КЭ входит в A_bt, если его центр попал в принятую полосу h_bt. Дополнительная проверка растяжения для бетона здесь не применяется. Для A_s при этом выбираются только растянутые стержни, потому что σ_s относится к растянутой арматуре."
    $row = Add-GuideParagraph $Sheet $row "Практические случаи для Effective: если x_t < 2a_s, глубина зоны принимается равной 2a_s, если только верхнее ограничение 0.5h не уменьшит ее. В этом случае по 2a_s расширяется именно бетонная зона A_bt; сжатые стержни, попавшие в эту полосу геометрически, не включаются в A_s. Если 2a_s ≤ x_t ≤ 0.5h, принимается фактическая растянутая зона x_t. Если x_t > 0.5h, зона ограничивается глубиной 0.5h."
    $row = Add-GuideParagraph $Sheet $row "A_bt считается дискретно: если центр бетонного элемента попал в принятую зону, учитывается вся его площадь; если не попал - площадь не учитывается. Частичные площади элементов текущая версия не считает."
    $row++

    $row = Add-GuideTitle $Sheet $row "10. A_s и напряжения σ_s" 13
    $row = Add-GuideParagraph $Sheet $row "В A_s входят только растянутые стержни, оси которых находятся внутри принятой зоны по координате s. Для Effective при срабатывании нижнего ограничения 2a_s бетонная площадь A_bt может увеличиться за счет полосы 2a_s, но сжатые стержни из этой полосы не добавляются в A_s, σ_s и d_s,eq. Набор стержней выбирается один раз по текущему сочетанию и затем используется также для σ_s,crc в режиме Auto, если уточнение вообще потребовалось."
    $row = Add-GuideFractionFormula $Sheet $row "σ_s =" "Σ(A_s,i · σ_s,i)" "ΣA_s,i" ""
    $row = Add-GuideParagraph $Sheet $row "A_s,i - площадь i-го выбранного растянутого стержня. σ_s,i - напряжение в этом стержне, полученное из НДМ."
    $row = Add-GuideParagraph $Sheet $row "ΣA_s,i = A_s - суммарная площадь выбранной растянутой арматуры. σ_s - средневзвешенное напряжение арматуры, которое входит в формулу раскрытия трещины."
    $row = Add-GuideParagraph $Sheet $row "Такой расчет σ_s является инженерной НДМ-интерпретацией для произвольного сечения и косого изгиба. СП 63.13330.2018, п. 8.2.16 дает формулы для типовых схем, а программа берет напряжения непосредственно из НДМ по каждому стержню."
    $row++

    $row = Add-GuideTitle $Sheet $row "11. Эквивалентный диаметр d_s,eq" 13
    $row = Add-GuideParagraph $Sheet $row "СП 63 в формуле l_s использует один диаметр d_s и не раскрывает общий случай нескольких диаметров в выбранной группе стержней. Поэтому программа применяет инженерное дополнение по EN 1992-1-1."
    $row = Add-GuideFractionFormula $Sheet $row "d_s,eq =" "Σ(n_i·d_i^2)" "Σ(n_i·d_i)" ""
    $row = Add-GuideParagraph $Sheet $row "d_s,eq - эквивалентный диаметр расчетной группы. d_i - диаметр стержней i-й группы, n_i - количество таких стержней."
    $row = Add-GuideParagraph $Sheet $row "Такой способ учета разных диаметров является инженерным дополнением. СП 63 не дает отдельной прямой формулы для этого случая."
    $row = Add-GuideParagraph $Sheet $row "Если все стержни одного диаметра, d_s,eq равен этому диаметру. Если диаметры разные, более крупные стержни получают больший вес, что инженерно согласуется с их большей площадью."
    $row++

    $row = Add-GuideTitle $Sheet $row "12. Коэффициенты φ_1, φ_2, φ_3 и ψ_s" 13
    $row = Add-GuideParagraph $Sheet $row "К этому шагу уже известны σ_s, E_s и l_s. Остается принять коэффициенты φ_1, φ_2, φ_3 и ψ_s из формулы (8.128)."
    $row = Add-GuideParagraph $Sheet $row "φ_1 - коэффициент длительности действия нагрузки. Программа берет его из SLS.Crack.Phi1; для продолжительного раскрытия обычно принимают 1.4."
    $row = Add-GuideParagraph $Sheet $row "φ_2 - коэффициент поверхности арматуры. Он задается пользователем напрямую в SLS.Crack.Phi2: обычный ориентир 0.5 для периодического профиля и 0.8 для гладкой арматуры."
    $row = Add-GuideParagraph $Sheet $row "φ_3 - коэффициент характера работы элемента. При SLS.Crack.Phi3Mode = Auto программа принимает φ_3 = 1.2 для растягивающей продольной силы N и φ_3 = 1.0 для остальных реализованных случаев. При Phi3Mode = User берется SLS.Crack.Phi3."
    $row = Add-GuideParagraph $Sheet $row "ψ_s - коэффициент неравномерности деформаций растянутой арматуры между трещинами. При SLS.Crack.PsiMode = User берется SLS.Crack.PsiS."
    $row = Add-GuideParagraph $Sheet $row "При SLS.Crack.PsiMode = Auto программа сначала считает ширину с ψ_s = 1. Если a_crc ≤ a_crc,ult, этого достаточно для проверки, но справочное σ_s,crc все равно выводится при наличии PostCrackState."
    $row = Add-GuideParagraph $Sheet $row "При SLS.Crack.PsiMode = AlwaysCalc программа всегда применяет уточнение ψ_s = 1 - 0.8·σ_s,crc/σ_s, если найдено состояние сразу после образования трещины. Если выбранный путь образования трещины не дает честной точки σ_s,crc, остается ψ_s = 1."
    $row = Add-GuideParagraph $Sheet $row "Если первая проверка Auto не проходит, ψ_s уточняется по напряжению арматуры сразу после появления трещины. Это напряжение берется из ранее сохраненного PostCrackState; повторно искать точку образования трещины на этом шаге не нужно."
    $row = Add-GuideParagraph $Sheet $row "σ_s,crc определяется для той же расчетной группы стержней, которая была выбрана по текущему сочетанию для σ_s. Это важно: программа сравнивает напряжения одной и той же группы стержней в текущем CrackedState и сразу после образования трещины."
    $row = Add-GuideParagraph $Sheet $row "В общем изгибе в эту группу входят только стержни, которые в текущем сочетании растянуты и оси которых попали в принятую расчетную зону. В центральном растяжении берется вся продольная арматура, которая находится в растяжении."
    $row = Add-GuideParagraph $Sheet $row "Если режим Effective расширил бетонную зону A_bt до 2a_s и эта полоса геометрически зашла за нейтральную линию, это влияет на A_bt. Сжатые стержни из такой полосы в A_s, σ_s и d_s,eq не добавляются: расчетная группа выбирается по текущему НДС как растянутая группа."
    $row = Add-GuideFractionFormula $Sheet $row "σ_s,crc =" "Σ(A_s,i · σ_s,i,crc)" "ΣA_s,i" ""
    $row = Add-GuideParagraph $Sheet $row "Здесь A_s,i - площадь i-го выбранного стержня, σ_s,i,crc - напряжение этого стержня из НДМ в состоянии λ_crc после образования трещины. Расчетная группа не пересобирается: берутся те же стержни, которые были выбраны по текущему CrackedState для σ_s."
    $row = Add-GuideParagraph $Sheet $row "В состоянии PostCrackState часть выбранных по текущему НДС стержней может оказаться сжатой: пороговая нагрузка λ_crc может быть меньше текущей, а после выключения растянутого бетона плоскость деформаций меняется. SLS.Crack.SigmaSCrcAveragingMode задает, что делать с такими сжатыми напряжениями при усреднении σ_s,crc: учитывать их со знаком или принимать равными нулю."
    $row = Add-GuideParagraph $Sheet $row "СП 63, п. 8.2.18 использует σ_s,crc как напряжение в продольной растянутой арматуре сразу после образования нормальных трещин."
    $row = Add-GuideParagraph $Sheet $row "Для произвольного сечения с несколькими стержнями программа получает одно σ_s,crc как средневзвешенное по площади напряжение выбранной группы стержней."
    $row = Add-GuideFractionFormula $Sheet $row "ψ_s = 1 - 0.8 ·" "σ_s,crc" "σ_s" "      СП 63, п. 8.2.18, ф. (8.137)"
    $row = Add-GuideParagraph $Sheet $row "σ_s - средневзвешенное напряжение той же группы стержней в текущем CrackedState."
    $row++

    $row = Add-GuideTitle $Sheet $row "13. Итоговый расчет и запас" 13
    $row = Add-GuideParagraph $Sheet $row "Условие проверки принято по СП 63.13330.2018, п. 8.2.6, формула (8.118). Допустимая ширина a_crc,ult всегда задается пользователем настройкой SLS.Crack.Allowable; программа не выбирает ее автоматически."
    $row = Add-GuideFormula $Sheet $row "a_crc ≤ a_crc,ult      СП 63, п. 8.2.6, ф. (8.118)"
    $row = Add-GuideFractionFormula $Sheet $row "SF_crc =" "a_crc,ult" "a_crc" ""
    $row = Add-GuideParagraph $Sheet $row "Обозначения: a_crc,ult - допустимая ширина раскрытия трещины, заданная пользователем; SF_crc - коэффициент запаса по раскрытию трещин. Если a_crc = 0, трещина не образована или расчет не применим, поэтому запас по раскрытию не ограничивает сечение."
    $row = Add-GuideParagraph $Sheet $row "В верхней сводке rngBatchSummary остаются только общий статус трещин и минимальный коэффициент запаса. Подробные величины расчета трещин выводятся в отдельной таблице Results от rngCrackSummaryAnchor: геометрия зоны, арматура, коэффициенты, напряжения, a_crc, a_crc,ult и статусы нормальных и продольных трещин."
    $row++

    $row = Add-GuideTitle $Sheet $row "13. Продольные трещины по сжатому бетону" 13
    $row = Add-GuideParagraph $Sheet $row "Эта проверка отделена от расчета ширины нормальных трещин a_crc. Она контролирует максимальное сжимающее напряжение в бетоне по уже найденному НДС сочетания и не запускает отдельный расчет равновесия."
    $row = Add-GuideParagraph $Sheet $row "По СП 35.13330.2011, п. 7.2 и таблице 7.1, образование продольных трещин относится к расчетам по второй группе предельных состояний. Поэтому программа выполняет эту проверку только как часть Calculation.Crack.Width. Если профиль не запрашивает раскрытие трещин, в Results выводится LongitudinalCrackStatus = N/A."
    $row = Add-GuideParagraph $Sheet $row "Программа просматривает бетонные элементы состояния с трещинами, берет максимальное по модулю сжимающее напряжение σ_c,max и сравнивает его с пользовательским Concrete.Rb.mc2. Если сжатого бетона нет, проверка неприменима: LongitudinalCrackStatus = N/A."
    $row = Add-GuideFormula $Sheet $row "σ_c,max ≤ R_b,mc2"
    $row = Add-GuideFractionFormula $Sheet $row "SF_long =" "R_b,mc2" "σ_c,max" ""
    $row = Add-GuideParagraph $Sheet $row "σ_c,max - максимальное по модулю сжимающее напряжение бетона в текущем CrackedState. R_b,mc2 - введенное пользователем предельное значение для проверки продольных трещин. SF_long - коэффициент запаса по этой проверке."
    $row = Add-GuideParagraph $Sheet $row "Concrete.Rb.mc2 вводится пользователем как итоговое допустимое значение для осевого сжатия при проверке продольных трещин. Программа не вычисляет и не умножает коэффициенты условий работы автоматически."
    $row = Add-GuideParagraph $Sheet $row "Нормативная привязка: СП 35.13330.2011, п. 7.100 требует проверять нормальные сжимающие напряжения от действующих нормативных нагрузок и воздействий. Таблица 7.6 выделяет расчетное сопротивление для осевого сжатия при проверках по предотвращению продольных трещин. Коэффициенты условий работы принимаются по применимым строкам таблицы 7.7; для этой проверки пользователь учитывает m_b13 и все другие нужные коэффициенты сам до ввода R_b,mc2."
    $row = Add-GuideParagraph $Sheet $row "То же правило принято для остальных характеристик бетона в Config: R_b, R_bt, R_b,ser и R_bt,ser считаются уже окончательно принятыми пользователем значениями с учетом нужных коэффициентов m. Это исключает скрытое повторное применение коэффициентов внутри программы."
    $row++

    $row = Add-GuideTitle $Sheet $row "14. Принятые инженерные допущения" 13
    $row = Add-GuideParagraph $Sheet $row "1. Геометрические расстояния h, x_t и a_s считаются по расчетной оболочке бетонных элементов. Если у элемента известны реальные стороны и поворот, используются они. Если таких данных нет, оболочка восстанавливается по площади и моментам инерции. Последний запасной вариант - квадрат той же площади. Эта оболочка нужна для границ и расстояний; реальные A/I элемента в механических расчетах не подменяются."
    $row = Add-GuideParagraph $Sheet $row "2. Площадь растянутого бетона A_bt считается по дискретной сетке. Если центр бетонного элемента попал в принятую растянутую или эффективную зону, в A_bt входит вся площадь этого элемента. Частичная площадь элемента на границе зоны отдельно не отрезается."
    $row = Add-GuideParagraph $Sheet $row "3. Для изгиба N + M эффективная растянутая зона ограничивается по глубине и фактической растянутой зоной. В расчет A_bt попадает бетонная часть принятой зоны, а не вся растянутая часть сечения, если ограничение эффективной зоны дает меньшую область."
    $row = Add-GuideParagraph $Sheet $row "4. При центральном растяжении эффективная зона вокруг отдельных стержней не ограничивается: для расчета ширины раскрытия используется вся продольная арматура, работающая на растяжение, и приведенная площадь сечения для N_crc."
    $row = Add-GuideParagraph $Sheet $row "5. Расстояние a_s берется от оси выбранного растянутого стержня до бетонной границы по нормали к нейтральной линии. Режим SLS.Crack.CoverDistanceMode выбирает, брать ближайшее пересечение с контуром или глобальную крайнюю точку сечения по этой нормали."
    $row = Add-GuideParagraph $Sheet $row "6. M_crc и N_crc не являются отдельным расчетом, который пользователь запускает вне Calculation.Crack.Width. Это промежуточные, но выводимые величины этапа проверки образования нормальной трещины. Они используются, чтобы определить, образуется ли нормальная трещина при текущем сочетании, и при необходимости уточнить ψ_s."
    $row = Add-GuideParagraph $Sheet $row "7. Для произвольного сечения программа использует одну общую расчетную группу растянутых стержней. По этой группе считаются A_s, σ_s, d_s,eq и σ_s,crc. Отдельные локальные зоны вокруг каждого стержня сейчас не строятся."
    $row = Add-GuideParagraph $Sheet $row "8. Если в выбранной группе есть стержни разных диаметров, применяется эквивалентный диаметр d_s,eq. Это инженерное дополнение по EN 1992-1-1 для случая, который СП 63 явно не раскрывает."
    $row = Add-GuideParagraph $Sheet $row "9. Нормативные ограничения расстояния между трещинами применяются к расчетному значению l_{s,0}, после чего в Results выводится принятое l_s. Поэтому l_s может отличаться от значения, полученного только по основной дробной формуле, если сработало ограничение."
    $row = Add-GuideParagraph $Sheet $row "10. Расчет непродолжительного раскрытия нормальных трещин в текущей версии не реализован. Проверка ведется для принятого продолжительного режима: пользователь задает коэффициенты φ_1, φ_2, φ_3 и ψ_s или выбирает предусмотренный автоматический режим."
    return $row + 2
}

# Формирует методический блок по фильтру продольного изгиба/устойчивости.
# Формулы выводятся тем же PNG-рендером, что и в разделе трещин, чтобы лист
# "Справка" оставался читаемым без OLE Equation и ручной верстки.
function Add-StabilityMethodologyGuide {
    param([object]$Sheet, [int]$StartRow)

    $row = $StartRow
    $row = Add-GuideParagraph $Sheet $row "Этот раздел описывает фильтр устойчивости, который может быть включен в расчетном профиле. Фильтр выполняется до НДМ: он берет исходные N, Mx, My, учитывает продольный изгиб по выбранному СП и передает дальше уже расчетные усилия. Сам solver НДМ при этом не меняется."
    $row = Add-GuideParagraph $Sheet $row "В текущей версии реализованы только ненапрягаемые стержни. Материалы для устойчивости выбираются строкой MaterialModel.Stability.ValueSet в профиле; программа не переключает их автоматически при выборе СП 35 или СП 63."
    $row = Add-GuideParagraph $Sheet $row "Если проверка устойчивости получает FAIL, остальные запрошенные расчеты НДС, несущей способности и трещин продолжаются, чтобы показать полную картину по сочетанию. Отказ устойчивости сохраняется в своем подробном блоке и влияет на общий статус; успешные результаты других проверок его не отменяют. Результаты этих расчетов не означают, что сочетание прошло проверку устойчивости."
    $row++

    $row = Add-GuideTitle $Sheet $row "1. Где включается расчет" 13
    $row = Add-GuideParagraph $Sheet $row "Расчет включается в профиле строкой Calculation.Stability.Enabled = Yes. Общая методика выбирается настройкой Stability.Code: SP63 или SP35. Нагрузки постоянной или постоянной плюс длительной части задаются отдельной таблицей на Config и сопоставляются с Combination ID."
    $row = Add-GuideParagraph $Sheet $row "Для SP63 пользователь задает постоянные + длительные нагрузки. Для SP35 пользователь задает постоянные нагрузки. Программа принимает эти значения как исходные данные и не пытается сама отделять длительную часть от полной нагрузки."
    $row = Add-GuideParagraph $Sheet $row "Плоскость 1 связана с первой главной осью приведенного сечения. Если главные оси совпадают с X/Y, плоскость 1 соответствует изгибу Mx вокруг X, то есть расчетной плоскости YZ и эксцентриситету по Y. Плоскость 2 соответствует My вокруг Y, расчетной плоскости XZ и эксцентриситету по X."
    $row++

    $row = Add-GuideTitle $Sheet $row "2. Перенос усилий и главные оси" 13
    $row = Add-GuideParagraph $Sheet $row "Пользователь задает нагрузки относительно бетонного центра и Load.ReferenceOffsetX/Y. Для устойчивости программа переносит моменты к центру тяжести приведенного сечения бетон + арматура, потому что именно по приведенному сечению считаются главные оси, радиусы инерции и ядровые расстояния."
    $row = Add-GuideFormula $Sheet $row "M_x,red = M_x,user + N · (Y_ref - Y_red)"
    $row = Add-GuideFormula $Sheet $row "M_y,red = M_y,user + N · (X_ref - X_red)"
    $row = Add-GuideParagraph $Sheet $row "Здесь M_x,user и M_y,user - пользовательские моменты до переноса, X_ref/Y_ref - пользовательская точка приложения нагрузки, а X_red/Y_red - центр тяжести приведенного сечения. Знак N берется во внутренней системе программы; на Results значения переводятся обратно через rngSignConventionSettings."
    $row = Add-GuideFormula $Sheet $row "M_1 = M_x,red·cos α + M_y,red·sin α"
    $row = Add-GuideFormula $Sheet $row "M_2 = -M_x,red·sin α + M_y,red·cos α"
    $row = Add-GuideParagraph $Sheet $row "M_1 и M_2 - компоненты момента в главных плоскостях приведенного сечения. α - угол главных осей приведенного сечения. Для круга и других почти симметричных сечений программа фиксирует α = 0, чтобы малый численный перекос сетки не раскладывал чистый Mx или My на две плоскости."
    $row = Add-GuideParagraph $Sheet $row "Перед расчетом и после фильтра устойчивости применяется общая настройка Calculation.ZeroMomentPerDepth. Момент, который меньше M_tol = значение·h, считается практически нулевым. Поэтому в итоговом блоке Results выводятся уже те моменты, которые реально пошли дальше в расчет сечения."
    $row = Add-GuideFormula $Sheet $row "M_tol = Calculation.ZeroMomentPerDepth · h"
    $row++

    $row = Add-GuideTitle $Sheet $row "3. Геометрические характеристики" 13
    $row = Add-GuideParagraph $Sheet $row "Площадь, центр, главные инерции и радиусы инерции берутся из дискретной модели CSectionModel. Для приведенного сечения бетон учитывается с весом 1, а арматура добавляется как (n - 1)As, потому что бетонная площадь в месте стержня уже входит в бетонную сетку."
    $row = Add-GuideFractionFormula $Sheet $row "n_s =" "E_s" "E_b" ""
    $row = Add-GuideFormula $Sheet $row "A_red = A_b + (n_s - 1) · A_s"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "i = √(" },
        @{ Kind = "Fraction"; Numerator = "I_red"; Denominator = "A_red" },
        @{ Kind = "Text"; Text = ")" }
    ) "" "i = √(I_red/A_red)"
    $row = Add-GuideFractionFormula $Sheet $row "r =" "I_red" "A_red · c" "      СП 35: ветвь выбирается по ядровому расстоянию"
    $row = Add-GuideParagraph $Sheet $row "n_s - коэффициент приведения арматуры к бетону. E_s и E_b - модули арматуры и бетона выбранной модели устойчивости. A_b - площадь бетона, A_s - суммарная площадь продольной арматуры, A_red и I_red - приведенные площадь и момент инерции в рассматриваемой главной плоскости."
    $row = Add-GuideParagraph $Sheet $row "i - радиус инерции приведенного сечения, r - ядровое расстояние, c - расстояние от центра тяжести приведенного сечения до крайней бетонной границы в нужную сторону."
    $row = Add-GuideParagraph $Sheet $row "Ядровое расстояние r здесь является линейной геометрической характеристикой приведенного сечения. Оно точно описывает границу отсутствия растяжения только тогда, когда фактический НДС работает с тем же отношением модулей, что и приведенное сечение. При выходе бетона или арматуры на нелинейные участки диаграмм это остается справочной величиной для выбора ветви устойчивости, а не точной границей нелинейного НДС."
    $row = Add-GuideParagraph $Sheet $row "h для случайного эксцентриситета и гибкости берется только по бетонному контуру: арматура не увеличивает внешний габарит, потому что стержни находятся внутри бетона. Но арматура участвует в A_red/I_red и поэтому влияет на i и r."
    $row = Add-GuideParagraph $Sheet $row "Для импортированной из AutoCAD сетки сначала используются реальные размеры и поворот бетонного элемента, если они доступны. Если стороны неизвестны, но есть надежные Ix/Iy/Ixy, программа восстанавливает эквивалентный прямоугольник. Если и этих данных нет, границы элемента восстанавливаются через квадрат той же площади со средним углом распознанной сетки."
    $row = Add-GuideFormula $Sheet $row "b_eq = h_eq = √A"
    $row = Add-GuideParagraph $Sheet $row "В этой формуле A - площадь бетонного элемента, а b_eq и h_eq - стороны квадратной оболочки, используемой только для границ элемента."
    $row++

    $row = Add-GuideTitle $Sheet $row "4. Случайный эксцентриситет" 13
    $row = Add-GuideParagraph $Sheet $row "Stability.AccidentalEccentricityMode задает, от какой длины считать случайный эксцентриситет. AutoWithL - нормативный режим с геометрической длиной L. AutoWithμL - проектная проверочная опция, где вместо L берется расчетная длина l_0 = μ·L. User - пользователь задает модуль эксцентриситета отдельно для двух главных плоскостей."
    $row = Add-GuideFormula $Sheet $row "l_0,1 = μ_1 · L;     l_0,2 = μ_2 · L"
    $row = Add-GuideParagraph $Sheet $row "Коэффициенты μ_1 и μ_2 пользователь задает именно по главным плоскостям приведенного сечения. Для круга и других сечений, где главные оси совпадают с X/Y, μ_1 относится к расчетной плоскости Mx/YZ, а μ_2 - к расчетной плоскости My/XZ."
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "e_a = max(" },
        @{ Kind = "Fraction"; Numerator = "L"; Denominator = "600" },
        @{ Kind = "Text"; Text = "; " },
        @{ Kind = "Fraction"; Numerator = "h"; Denominator = "30" },
        @{ Kind = "Text"; Text = "; 10 мм)" }
    ) "СП 63, п. 8.1.7" "e_a = max(L/600; h/30; 10 мм)      СП 63, п. 8.1.7"
    $row = Add-GuideFractionFormula $Sheet $row "e_{c,sl} =" "L" "400" "      СП 35, п. 7.52"
    $row = Add-GuideParagraph $Sheet $row "L - геометрическая длина элемента, μ_1 и μ_2 - коэффициенты расчетной длины по главным плоскостям, l_0 - расчетная длина. e_a - случайный эксцентриситет по СП 63, e_c,sl - случайный эксцентриситет по СП 35."
    $row = Add-GuideParagraph $Sheet $row "Stability.AccidentalEccentricityPlanes = OnlyMomentPlane сохраняет принятое упрощение проекта: если момент есть только в одной главной плоскости, случайный эксцентриситет добавляется только в этой плоскости. BothPlanes добавляет его в обеих главных плоскостях."
    $row = Add-GuideParagraph $Sheet $row "Если момент в плоскости ненулевой, знак случайного эксцентриситета выбирается так, чтобы увеличить модуль этого момента. Если момент равен нулю, направление берется из Stability.ZeroMomentEccentricitySign1/2."
    $row++

    $row = Add-GuideTitle $Sheet $row "5. Начальный эксцентриситет" 13
    $row = Add-GuideParagraph $Sheet $row "В формулах устойчивости N рассматривается как положительная сжимающая сила. Для статически определимой схемы программа складывает фактический и случайный эксцентриситет. Для статически неопределимой схемы принимает больший по модулю из двух, сохраняя направление расчетного момента."
    $row = Add-GuideFractionFormula $Sheet $row "e_stat =" "M" "N" ""
    $row = Add-GuideFormula $Sheet $row "стат. опред.:     e_0 = e_stat + e_a"
    $row = Add-GuideFormula $Sheet $row "стат. неопред.:  e_0 = sign · max(|e_stat|; |e_a|)"
    $row = Add-GuideParagraph $Sheet $row "M - момент в рассматриваемой главной плоскости, N - сжимающая продольная сила, e_stat - статический эксцентриситет. sign - знак расчетного момента; он нужен, чтобы случайный эксцентриситет добавлялся в физически выбранную сторону."
    $row = Add-GuideParagraph $Sheet $row "Для СП 35 в Results то же расчетное значение выводится как e_c, а случайный эксцентриситет - как e_c,sl. Для СП 63 эти величины выводятся как e_0 и e_a."
    $row++

    $row = Add-GuideTitle $Sheet $row "6. Расчет по СП 63" 13
    $row = Add-GuideParagraph $Sheet $row "Для каждой главной плоскости программа считает условную жесткость D, критическую силу N_cr и коэффициент η. Если гибкость l_0/i не больше 14, влияние прогиба по СП 63 не учитывается и η принимается равным 1; N_cr при этом все равно выводится справочно."
    $row = Add-GuideFractionFormula $Sheet $row "φ_l = 1 +" "M_{l1}" "M_1" ";  φ_l ≤ 2      СП 63, п. 8.1.15"
    $row = Add-GuideParagraph $Sheet $row "M_1 и M_l1 считаются не в центре сечения, а относительно центра наиболее растянутого или наименее сжатого стержня арматуры. Если арматуры нет, программа использует край бетонного контура как расчетный fallback."
    $row = Add-GuideFractionFormula $Sheet $row "δ_e =" "|e_0|" "h" "      СП 63, п. 8.1.15"
    $row = Add-GuideParagraph $Sheet $row "В программе δ_e дополнительно ограничивается настройками Stability.SP63.DeltaEMin и Stability.SP63.DeltaEMax. Это расчетные границы, видимые на Config."
    $row = Add-GuideFractionFormula $Sheet $row "k_b =" "0.15" "φ_l · (0.3 + δ_e)" "      СП 63, п. 8.1.15"
    $row = Add-GuideFormula $Sheet $row "D = k_b · E_b · I_b + k_s · E_s · I_s      СП 63, п. 8.1.15"
    $row = Add-GuideFractionFormula $Sheet $row "N_cr =" "π^2 · D" "l_0^2" "      СП 63, п. 8.1.15"
    $row = Add-GuideFractionFormula $Sheet $row "η =" "N_cr" "N_cr - N" "      СП 63, п. 8.1.15; эквивалентная запись нормативной формулы"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "если " },
        @{ Kind = "Fraction"; Numerator = "l_0"; Denominator = "i" },
        @{ Kind = "Text"; Text = " ≤ 14, то η = 1" }
    ) "" "если l_0/i ≤ 14, то η = 1"
    $row = Add-GuideFormula $Sheet $row "M_design = η · N · e_0"
    $row = Add-GuideParagraph $Sheet $row "φ_l учитывает длительную часть момента, δ_e - относительный эксцентриситет, k_b - коэффициент бетонной части жесткости, k_s - пользовательский коэффициент арматурной части. I_b и I_s - моменты инерции бетона и арматуры в рассматриваемой плоскости. N_cr - критическая сила, η - коэффициент увеличения момента от продольного изгиба."
    $row = Add-GuideParagraph $Sheet $row "Если N достигла или превысила N_cr, η не имеет корректного положительного значения. В этом случае плоскость получает FAIL, а дальнейший НДМ для LC не запускается."
    $row++

    $row = Add-GuideTitle $Sheet $row "7. Расчет по СП 35: выбор ветви" 13
    $row = Add-GuideParagraph $Sheet $row "СП 35 в реализованной ветви сначала сравнивает модуль расчетного эксцентриситета e_c с ядровым расстоянием r. Для несимметричного сечения программа выбирает r со стороны, куда направлен e_c."
    $row = Add-GuideFormula $Sheet $row "|e_c| > r  >  ветвь через N_cr и η"
    $row = Add-GuideFormula $Sheet $row "|e_c| ≤ r  >  табличная ветвь через таблицу 7.21"
    $row = Add-GuideParagraph $Sheet $row "Таблица 7.21 СП 35 хранится на Config в отдельном диапазоне. Значения не зашиты в VBA: программа интерполирует только по тому содержимому таблицы, которое видит в книге."
    $row++

    $row = Add-GuideTitle $Sheet $row "8. СП 35 при e_c > r" 13
    $row = Add-GuideParagraph $Sheet $row "Для больших эксцентриситетов программа считает условную жесткость, критическую силу и η. В этой ветви сохраняется структура формулы (7.10) СП 35: π² дополнительно не добавляется."
    $row = Add-GuideFractionFormula $Sheet $row "φ_l = 1 +" "M_l" "M" ";  1 ≤ φ_l ≤ 2      СП 35, п. 7.54, ф. (7.11)"
    $row = Add-GuideParagraph $Sheet $row "M и M_l считаются относительно наиболее растянутой или наименее сжатой грани. Если знаки M и M_l противоположны, применяется специальная ветвь СП 35: при |e_c| ≤ 0.1·h принимается φ_l = 1, иначе φ_l = 1.05."
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "δ = max(" },
        @{ Kind = "Fraction"; Numerator = "|e_c|"; Denominator = "h" },
        @{ Kind = "Text"; Text = "; 0.5 - 0.01 · " },
        @{ Kind = "Fraction"; Numerator = "l_0"; Denominator = "h" },
        @{ Kind = "Text"; Text = " - 0.01 · R_b)" }
    ) "" "δ = max(|e_c|/h; 0.5 - 0.01·l_0/h - 0.01·R_b)"
    $row = Add-GuideFractionFormula $Sheet $row "δ_p =" "δ" "φ_p" ""
    $row = Add-GuideFractionFormula $Sheet $row "k_1 =" "0.11" "0.1 + δ_p" "+ 0.1      СП 35, п. 7.54, ф. (7.10)"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "D = 6.4 · E_b · [" },
        @{ Kind = "Fraction"; Numerator = "I_b"; Denominator = "φ_l" },
        @{ Kind = "Text"; Text = " · k_1 + " },
        @{ Kind = "Fraction"; Numerator = "E_s"; Denominator = "E_b" },
        @{ Kind = "Text"; Text = " · I_s]" }
    ) "СП 35, п. 7.54, ф. (7.10)" "D = 6.4 · E_b · [I_b/φ_l · k_1 + (E_s/E_b) · I_s]      СП 35, п. 7.54, ф. (7.10)"
    $row = Add-GuideFractionFormula $Sheet $row "N_cr =" "D" "l_0^2" "      СП 35, п. 7.54, ф. (7.10)"
    $row = Add-GuideFractionFormula $Sheet $row "η =" "N_cr" "N_cr - N" "      эквивалентная запись нормативной формулы"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Fraction"; Numerator = "N"; Denominator = "N_cr" },
        @{ Kind = "Text"; Text = " ≤ limit, где limit = Stability.SP35.NOverNcrLimit" }
    ) "СП 35, п. 7.54" "N/N_cr ≤ limit, где limit = Stability.SP35.NOverNcrLimit      СП 35, п. 7.54"
    $row = Add-GuideFormula $Sheet $row "M_design = η · N · e_c"
    $row = Add-GuideParagraph $Sheet $row "δ - расчетная относительная величина из формулы СП 35, δ_p - величина δ с учетом φ_p, k_1 - коэффициент в жесткости D. R_b в формуле δ берется в МПа. limit - пользовательское ограничение отношения N/N_cr для этой ветви."
    $row = Add-GuideParagraph $Sheet $row "Stability.PhiLMode = PhiL2 в этой ветви принудительно принимает φ_l = 2. В режиме Auto программа считает φ_l по моментам полной и постоянной нагрузки и затем ограничивает его диапазоном 1...2."
    $row++

    $row = Add-GuideTitle $Sheet $row "9. СП 35 при e_c ≤ r" 13
    $row = Add-GuideParagraph $Sheet $row "Для малых эксцентриситетов используется табличная ветвь. Программа интерполирует φ_m по отношению e_c/r между столбцами таблицы 7.21, затем интерполирует φ_m и φ_l между соседними строками по гибкости l_0/i."
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "φ_m = interp(table 7.21; " },
        @{ Kind = "Fraction"; Numerator = "e_c"; Denominator = "r" },
        @{ Kind = "Text"; Text = "; " },
        @{ Kind = "Fraction"; Numerator = "l_0"; Denominator = "i" },
        @{ Kind = "Text"; Text = ")" }
    ) "" "φ_m = interp(table 7.21; e_c/r; l_0/i)"
    $row = Add-GuideCompositeFormula $Sheet $row @(
        @{ Kind = "Text"; Text = "φ_l = interp(table 7.21; " },
        @{ Kind = "Fraction"; Numerator = "l_0"; Denominator = "i" },
        @{ Kind = "Text"; Text = ")" }
    ) "" "φ_l = interp(table 7.21; l_0/i)"
    $row = Add-GuideFractionFormula $Sheet $row "φ_l =" "N_l" "N" ""
    $row = Add-GuideFractionFormula $Sheet $row "φ_{ml} =" "φ_m" "φ_l" ""
    $row = Add-GuideFractionFormula $Sheet $row "φ =" "φ_m" "φ_l·φ_{ml} + (1 - φ_l)" "      СП 35, п. 7.55, ф. (7.15)"
    $row = Add-GuideFormula $Sheet $row "N_ult,stab = φ · (R_b · A_b,stab + R_sc · A_s)"
    $row = Add-GuideFractionFormula $Sheet $row "SF_stab =" "N_ult,stab" "N" ""
    $row = Add-GuideFormula $Sheet $row "N ≤ N_ult,stab"
    $row = Add-GuideParagraph $Sheet $row "φ_m и φ_l в этой ветви берутся интерполяцией таблицы 7.21. N_l - длительная часть продольной силы, φ_ml - вспомогательный коэффициент формулы СП 35, φ - итоговый коэффициент снижения несущей способности. A_b,stab - бетонная площадь для этой проверки, R_sc - расчетное сопротивление сжатой арматуры."
    $row = Add-GuideParagraph $Sheet $row "В этой табличной ветви настройка Stability.PhiLMode = PhiL2 не подменяет табличное φ_l: используются значения из таблицы 7.21. Если площадь арматуры больше 3% gross-площади бетона, в формуле N_ult бетонный вклад уменьшается на A_s; это отдельное правило формулы устойчивости и не дублирует приведение (n - 1)A_s."
    $row++

    $row = Add-GuideTitle $Sheet $row "10. Что выводится в Results" 13
    $row = Add-GuideParagraph $Sheet $row "Подробная таблица устойчивости показывает четыре блока: итог по расчету, общие данные по главным осям, расчет по СП 35 и расчет по СП 63. Таблица всегда имеет постоянную форму, но заполняется только тот нормативный блок, который выбран настройкой Stability.Code."
    $row = Add-GuideParagraph $Sheet $row "В блоке Итог по расчету моменты после учета η выводятся в трех привязках: M1/M2 в главных осях приведенного сечения, Mx/My относительно центральных осей приведенного сечения и Mx/My в пользовательской точке приложения нагрузки. Эти значения уже прошли общий фильтр практически нулевого момента."
    $row = Add-GuideParagraph $Sheet $row "Для ветви СП 35 e_c > r в Results выводится запас limit·N_cr/N, где limit берется из Stability.SP35.NOverNcrLimit. Для табличной ветви СП 35 выводится N_ult/N, для СП 63 - N_cr/N. Если применимый запас меньше единицы, LC получает FAIL по устойчивости."
    $row = Add-GuideParagraph $Sheet $row "Все значения перед выводом проходят через CUnitSystem: единицы и знаки берутся из rngUnitSettings и rngSignConventionSettings."
    return $row + 2
}

# Формирует финальный справочный раздел по листу Results.
# Здесь описываются не настройки Config, а смысл основных выходных диапазонов
# расчетного снимка, особенно геометрические характеристики бетонного и
# приведенного сечения.
function Add-ResultsSheetGuide {
    param([object]$Sheet, [int]$StartRow)

    $row = $StartRow
    $row = Add-GuideParagraph $Sheet $row "Лист Results хранит расчетный снимок последнего завершенного запуска, включая не прошедшие проверки и диагностические состояния. Схема на листе Расчет и AutoCAD export читают именно этот снимок: они не перечитывают текущие исходные данные Config и не запускают solver заново."
    $row = Add-GuideParagraph $Sheet $row "Все численные результаты перед записью проходят через CUnitSystem. Поэтому единицы и знаки на Results соответствуют настройкам rngUnitSettings и rngSignConventionSettings, а не внутренним Н, мм и внутреннему знаку сжатия."
    $row++

    $row = Add-GuideTitle $Sheet $row "1. Верхняя сводка" 13
    $row = Add-GuideParagraph $Sheet $row "rngBatchSummary показывает одну строку на сочетание: общий статус, статусы прочности, трещин и устойчивости, а также минимальные коэффициенты запаса. Строка worst LC над таблицей показывает, какое сочетание оказалось определяющим по выбранному критерию General.WorstCombinationCriterion."
    $row = Add-GuideParagraph $Sheet $row "Если конкретная проверка не включена профилем, в строке сочетания выводится N/A. Это не ошибка расчета, а признак, что выбранный профиль не запрашивал эту ветку."
    $row++

    $row = Add-GuideTitle $Sheet $row "2. Подробные таблицы проверок" 13
    $row = Add-GuideParagraph $Sheet $row "rngStrengthSummaryAnchor выводит прямой НДС по модели прочности и поиск несущей способности. В этих таблицах плоскость деформаций, предельные деформации, напряжения, h/x и запас относятся именно к модели прочности выбранного профиля."
    $row = Add-GuideParagraph $Sheet $row "rngCrackSummaryAnchor выводит проверку образования нормальной трещины, расчет ширины раскрытия и проверку продольных трещин. Если состояние трещинообразования неприменимо, ключевые поля получают N/A, а CrackedState все равно может использоваться для продольных трещин."
    $row = Add-GuideParagraph $Sheet $row "rngStabilitySummaryAnchor выводит фильтр продольного изгиба и устойчивости: нагрузки в центре приведенного сечения, главные плоскости, коэффициенты η/Ncr/Nult и итоговые усилия после учета устойчивости."
    $row++

    $row = Add-GuideTitle $Sheet $row "3. Геометрия элементов" 13
    $row = Add-GuideParagraph $Sheet $row "rngNDMSectionGeometry содержит расчетные бетонные элементы и стержни. Для бетона Area, LocalIx, LocalIy и LocalIxy являются расчетными характеристиками элемента. Width, Height и Rotation описывают только геометрическую оболочку для границ, схемы, h, a_s и AutoCAD."
    $row = Add-GuideParagraph $Sheet $row "Если Geometry.Source = AutoCAD, исходная расчетная сетка берется из объектов Region на заданных слоях. Importer читает фактические Area, координаты центра, локальные Ix/Iy/Ixy и найденную арматуру. После этого данные записываются в тот же CSectionModel, что и параметрические сечения, поэтому дальнейший расчет не различает источник геометрии."
    $row = Add-GuideParagraph $Sheet $row "Реальные характеристики импортированных бетонных элементов не заменяются размерами оболочки. Если AutoCAD дал Area и Ix/Iy/Ixy, именно эти значения идут в НДМ, приведенное сечение, перенос по Штейнеру, радиусы инерции и устойчивость. Width, Height и Rotation нужны только там, где программе нужна форма элемента: границы, расстояния до контура, схема и AutoCAD export."
    $row = Add-GuideParagraph $Sheet $row "Если точная форма импортированного элемента неизвестна, CSectionModel строит согласованную прямоугольную оболочку по реальным характеристикам. Это не попытка доказать, что Region был прямоугольником, а только удобное представление границы расчетной ячейки."
    $row++

    $row = Add-GuideTitle $Sheet $row "4. Результаты элементов по состояниям" 13
    $row = Add-GuideParagraph $Sheet $row "rngNDMElementResults содержит деформации и напряжения элементов для сохраненных named-state: StrengthState, CapacityState, PreCrackState, PostCrackState, CrackedState и других состояний, которые реально были посчитаны для сочетания."
    $row = Add-GuideParagraph $Sheet $row "Если пользователь просит показать на схеме состояние, которого нет для выбранного сочетания, программа должна вывести понятное сообщение вместо молчаливой подстановки другого состояния."
    $row++

    $row = Add-GuideTitle $Sheet $row "5. Свойства бетонного и приведенного сечения" 13
    $row = Add-GuideParagraph $Sheet $row "rngNDMSectionProperties содержит свойства уровня всего сечения. Блок Concrete.* относится только к бетонной части. Блок Transformed.* относится к приведенному сечению бетон + продольная арматура в бетонной базе."
    $row = Add-GuideParagraph $Sheet $row "Приведение выполняется через обычные модули E_s/E_b соответствующей модели. Так как бетонная сетка уже занимает всю площадь бетона, вклад арматуры добавляется как дополнительная часть, эквивалентная (n_s - 1)A_s. Это не меняет реальные свойства отдельных бетонных элементов, а дает справочное линейное сечение бетон + арматура."
    $row = Add-GuideParagraph $Sheet $row "Area - площадь выбранного представления. CentroidX/Y - координаты центра тяжести в координатах модели. Ix/Iy/Ixy - моменты относительно осей внутренней системы координат модели. Ixc/Iyc/Ixyc - центральные моменты относительно осей X/Y, проходящих через центр тяжести этого же представления."
    $row = Add-GuideParagraph $Sheet $row "PrincipalAngle - угол от +X модели к главной центральной оси 1, положительный против часовой стрелки. PrincipalI1 - момент инерции относительно главной оси 1 и является большим главным моментом. PrincipalI2 - момент относительно главной оси 2 и является меньшим главным моментом."
    $row = Add-GuideParagraph $Sheet $row "RadiusX/Y и PrincipalRadius1/2 - радиусы инерции по соответствующим центральным или главным осям. Они нужны для ручных проверок, устойчивости и понимания жесткости сечения по разным направлениям."
    $row++

    $row = Add-GuideTitle $Sheet $row "6. Ядровые расстояния r" 13
    $row = Add-GuideParagraph $Sheet $row "CoreDistance - это ядровое расстояние r: предельный эксцентриситет продольной сжимающей силы, при котором в линейном приведенном сечении крайнее волокно с противоположной стороны доходит до нулевой деформации. Если сжимающая сила приложена ближе к центру, чем r в выбранном направлении, линейная теория дает один знак деформаций по всему бетонному контуру."
    $row = Add-GuideFractionFormula $Sheet $row "r =" "I" "A · c" ""
    $row = Add-GuideParagraph $Sheet $row "A и I берутся у выбранного представления: Concrete или Transformed. c - расстояние от центра тяжести этого представления до крайней бетонной границы в направлении, противоположном рассматриваемому эксцентриситету. Арматура влияет на A и I приведенного сечения, но не расширяет внешний бетонный контур."
    $row = Add-GuideParagraph $Sheet $row "Суффиксы Plus и Minus относятся к направлению эксцентриситета, а не к стороне крайнего волокна. Например CoreDistanceYMinus - допустимый эксцентриситет в направлении -Y; для его расчета используется крайняя бетонная граница с противоположной стороны, потому что именно она первой выходит на нулевую деформацию."
    $row = Add-GuideParagraph $Sheet $row "CoreDistanceXPlus/Minus и CoreDistanceYPlus/Minus заданы по центральным осям X/Y, параллельным внутренним осям модели. CoreDistance1Plus/Minus и CoreDistance2Plus/Minus заданы по главным центральным осям 1 и 2. Это именно направления осей, а не главные плоскости устойчивости."
    $row = Add-GuideParagraph $Sheet $row "Для устойчивости по СП 35 программа использует r приведенного сечения в соответствующей главной плоскости, чтобы выбрать ветвь e_c > r или e_c ≤ r. В detailed Results это рядом с расчетом устойчивости подписано через плоскости, а в rngNDMSectionProperties значения CoreDistance1/2 подписаны именно как направления главных осей."
    $row = Add-GuideParagraph $Sheet $row "Почему r не всегда совпадает с фактическим НДС один в один. При расчете r программа использует обычную линейную идею приведенного сечения: бетон работает с модулем E_b, арматура - с модулем E_s, а их отношение задает коэффициент приведения n_s = E_s/E_b. В такой модели жесткость материалов постоянна, поэтому граница ядра получается чисто геометрической."
    $row = Add-GuideParagraph $Sheet $row "На ThreeLine-диаграмме бетона есть начальный прямой участок с наклоном E_b. Пока деформации сечения остаются на этом участке, фактический НДС решателя использует тот же наклон бетона, что и расчет приведенного сечения. Поэтому проверка по r обычно сходится очень хорошо: расчетная граница ядра и фактическая граница появления растяжения почти совпадают, с учетом дискретизации сетки."
    $row = Add-GuideParagraph $Sheet $row "На TwoLine-диаграмме бетона начальный наклон в рабочей части не совпадает с обычным E_b из приведения: диаграмма сразу идет к расчетному сопротивлению и дальше имеет плато. Поэтому фактическая жесткость в НДМ отличается от жесткости, принятой в Transformed.*, и r остается полезной справочной характеристикой, но уже не обязан точно совпадать с границей нулевой деформации в нелинейном расчете."
    $row = Add-GuideParagraph $Sheet $row "Если бетон или арматура вышли из начального линейного участка, если растянутый бетон отключен или часть сечения уже работает по плато, совпадение с r также ухудшается. Это не ошибка вывода r: просто r относится к линейному приведенному сечению, а solver считает фактическую нелинейную диаграмму материалов."
    $row++

    $row = Add-GuideTitle $Sheet $row "7. Материальные диаграммы и аннотации" 13
    $row = Add-GuideParagraph $Sheet $row "rngNDMMaterialDiagrams хранит фактические точки диаграмм материалов, которые использовались в расчете. Это удобно для проверки, какая именно модель попала в StrengthState, CrackInitiation или CrackedState."
    $row = Add-GuideParagraph $Sheet $row "rngNDMSectionAnnotations хранит semantic-аннотации: контур, размеры, подписи арматуры и служебные линии. Excel-схема и AutoCAD export читают эти данные из Results, поэтому после расчета они воспроизводят тот же snapshot."
    $row = Add-GuideParagraph $Sheet $row "Контур нужен только для параметрических сечений, где программа точно знает исходную внешнюю границу: Circle, RectSet, RoundedRectangle и HollowRectangle. По нему строится более чистая схема, размерные линии и непрерывный контур AutoCAD export. Для импортированной AutoCAD-сетки точный исходный контур специально не восстанавливается: расчет и визуализация используют сохраненные элементы и их оболочки."
    return $row + 2
}

# Добавляет лист "Справка" и прямые гиперссылки "Подробнее" из Config на конкретные ячейки справки.
function Add-SettingsInstructions {
    param([object]$Workbook, [object]$ConfigSheet, [object]$InstructionSheet)

    Clear-GuideFormulaPictures $InstructionSheet
    $script:FormulaImageCounter = 0
    $script:FormulaImageRows.Clear()

    $InstructionSheet.Cells.Clear()
    try { $InstructionSheet.Cells.ClearOutline() } catch {}
    try { $InstructionSheet.Rows.Hidden = $false } catch {}
    try { $InstructionSheet.Outline.SummaryRow = 0 } catch {}
    $InstructionSheet.Cells.Validation.Delete()
    $InstructionSheet.Cells.Font.Name = "Arial"
    $InstructionSheet.Cells.Font.Size = 10
    $InstructionSheet.Columns.Item(1).ColumnWidth = 34
    $InstructionSheet.Columns.Item(2).ColumnWidth = 118
    $InstructionSheet.Columns.Item(3).ColumnWidth = 18
    $InstructionSheet.Columns.Item(4).ColumnWidth = 18
    $InstructionSheet.Columns.Item(5).ColumnWidth = 26
    $InstructionSheet.Columns.Item(6).ColumnWidth = 26
    $InstructionSheet.Columns.Item(1).WrapText = $true
    $InstructionSheet.Columns.Item(2).WrapText = $true
    $InstructionSheet.Columns.Item(3).WrapText = $true
    $InstructionSheet.Columns.Item(4).WrapText = $true
    $InstructionSheet.Columns.Item(5).WrapText = $true
    $InstructionSheet.Columns.Item(6).WrapText = $true

    $row = 1
    $row = Add-CollapsibleGuideSection $InstructionSheet $row "Поиск НДС текущего сочетания" {
        param($sheet, $startRow)
        Add-DirectStateMethodologyGuide $sheet $startRow
    }
    $row = Add-CollapsibleGuideSection $InstructionSheet $row "Поиск предельной несущей способности" {
        param($sheet, $startRow)
        Add-CapacityMethodologyGuide $sheet $startRow
    }
    $row = Add-CollapsibleGuideSection $InstructionSheet $row "Расчет ширины раскрытия нормальных трещин" {
        param($sheet, $startRow)
        Add-CrackWidthMethodologyGuide $sheet $startRow
    }
    $row = Add-CollapsibleGuideSection $InstructionSheet $row "Расчет продольного изгиба и устойчивости" {
        param($sheet, $startRow)
        Add-StabilityMethodologyGuide $sheet $startRow
    }

    $row = Add-GuideTitle $InstructionSheet $row "Справка по настройкам листа Config" 16
    $configSettingsBodyStartRow = $row

    $InstructionSheet.Cells.Item($row, 1).Value2 = "Нормативные источники"
    $InstructionSheet.Cells.Item($row, 1).Font.Bold = $true
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "СП 63.13330.2018"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Бетонные и железобетонные конструкции. Основные положения. Используется как основной источник по НДМ и трещиностойкости; точные пункты указаны только там, где они уже подтверждены в документации проекта."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "СП 35.13330.2011"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Мосты и трубы. Используется как потенциальный специальный источник для мостовых параметров; непроверенные ссылки не подставляются автоматически."
    $row += 2
    $InstructionSheet.Cells.Item($row, 1).Value2 = "Важно"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Справка описывает фактически реализованное поведение программы. Если нормативная ссылка не подтверждена, это отмечается как требующее дальнейшей трассировки."
    $row += 2

    $InstructionSheet.Cells.Item($row, 1).Value2 = "Словарь пользовательских статусов"
    $InstructionSheet.Cells.Item($row, 1).Font.Bold = $true
    $InstructionSheet.Cells.Item($row, 1).Interior.Color = 15921906
    $InstructionSheet.Cells.Item($row, 2).Interior.Color = 15921906
    $statusTableStart = $row
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "OK"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Расчет этой проверки выполнен успешно. Для прямого НДС равновесие найдено внутри физической диаграммы материала; для прочности или трещин проверка прошла."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "FAIL"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Численное решение есть, но инженерная проверка не проходит: превышена несущая способность, ширина нормальной трещины больше допуска, sigma_c,max больше Rb,mc2 по продольным трещинам или прямое НДС найдено только за пределами физической диаграммы."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "BaseFail"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Сечение не выдерживает уже постоянную часть выбранного пути несущей способности, при λ = 0. Физический отказ подтвержден; это не просто несходимость решателя."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "NumFail"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Программа не смогла найти равновесие или предельную точку с текущими численными настройками. Это не доказательство разрушения; нужно проверить диагностику, нагрузку, сетку и параметры расчета."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "InputErr"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Результат не получен из-за ошибки исходных данных или настройки: обязательная пустая ячейка, неизвестный вариант, недопустимая геометрия, материал, единицы или строка сочетания. Ошибка могла быть обнаружена до запуска либо при подготовке конкретной проверки; место и причина указаны в комментарии."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "CalcErr"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Нарушен внутренний контракт расчета или произошла программная ошибка. Это не физический отказ и не обычная несходимость. Сохраните комментарий и txt-отчет для диагностики."
    $row++
    $InstructionSheet.Cells.Item($row, 1).Value2 = "N/A"
    $InstructionSheet.Cells.Item($row, 2).Value2 = "Проверка не запрошена, неприменима либо не выполнена из-за отсутствия обязательного предыдущего результата. В последнем случае причина указана в комментарии, а фактический отказ остается в статусе соответствующего НДС или поиска и в общей сводке. N/A само по себе не означает успешную проверку."
    $InstructionSheet.Range($InstructionSheet.Cells.Item($statusTableStart, 1), $InstructionSheet.Cells.Item($row, 2)).Borders.LineStyle = 1
    $InstructionSheet.Range($InstructionSheet.Cells.Item($statusTableStart, 1), $InstructionSheet.Cells.Item($row, 2)).Borders.Color = 14277081
    $row += 3

    $anchors = @{}
    foreach ($item in (Get-SettingsInstructionCatalog)) {
        $anchors[$item.Key] = $row
        $InstructionSheet.Cells.Item($row, 1).Value2 = $item.Title
        $InstructionSheet.Cells.Item($row, 1).Font.Bold = $true
        $InstructionSheet.Cells.Item($row, 1).Interior.Color = 15921906
        $InstructionSheet.Cells.Item($row, 2).Interior.Color = 15921906
        $row++
        $lineNumber = 1
        foreach ($line in $item.Lines) {
            $InstructionSheet.Cells.Item($row, 1).Value2 = [string]$lineNumber
            $InstructionSheet.Cells.Item($row, 2).Value2 = $line
            $InstructionSheet.Cells.Item($row, 2).IndentLevel = 1
            if ($line.StartsWith("Формула")) {
                $formulaCell = $InstructionSheet.Cells.Item($row, 2)
                $formulaCell.Font.Name = "Arial"
                $formulaCell.Font.Size = 11
                $formulaCell.Font.Italic = $true
                $formulaCell.Interior.Color = 16448250
                $formulaCell.Font.Color = 3355443
            }
            $row++
            $lineNumber++
        }
        if ($item.ContainsKey("Tables")) {
            foreach ($table in $item.Tables) {
                $row++
                $InstructionSheet.Cells.Item($row, 2).Value2 = $table.Title
                $InstructionSheet.Cells.Item($row, 2).Font.Bold = $true
                $InstructionSheet.Cells.Item($row, 2).Interior.Color = 15921906
                $row++

                for ($c = 0; $c -lt $table.Headers.Count; $c++) {
                    $cell = $InstructionSheet.Cells.Item($row, 2 + $c)
                    $cell.Value2 = $table.Headers[$c]
                    $cell.Font.Bold = $true
                    $cell.Interior.Color = 14277081
                    $cell.WrapText = $true
                    $cell.HorizontalAlignment = -4131
                }
                $row++

                $tableStartRow = $row - 1
                foreach ($dataRow in $table.Rows) {
                    for ($c = 0; $c -lt $dataRow.Count; $c++) {
                        $cell = $InstructionSheet.Cells.Item($row, 2 + $c)
                        $cell.Value2 = $dataRow[$c]
                        $cell.WrapText = $true
                        $cell.VerticalAlignment = -4160
                    }
                    $row++
                }

                $tableEndColumn = 1 + $table.Headers.Count
                $tableRange = $InstructionSheet.Range($InstructionSheet.Cells.Item($tableStartRow, 2), $InstructionSheet.Cells.Item($row - 1, $tableEndColumn))
                $tableRange.Borders.LineStyle = 1
                $tableRange.Borders.Color = 14277081
                $row++
            }
        }
        $row++
    }
    $configSettingsBodyEndRow = $row - 1
    if ($configSettingsBodyEndRow -ge $configSettingsBodyStartRow) {
        try {
            $InstructionSheet.Range($InstructionSheet.Cells.Item($configSettingsBodyStartRow, 1), $InstructionSheet.Cells.Item($configSettingsBodyEndRow, 1)).EntireRow.Group() | Out-Null
        }
        catch {
            # Если Excel не дал создать outline-группу, текстовый раздел все равно
            # остается на листе и ссылки "Подробнее" продолжают вести в нужные строки.
        }
    }

    $row = Add-CollapsibleGuideSection $InstructionSheet $row "Справка по результатам расчета листа Results" {
        param($sheet, $startRow)
        Add-ResultsSheetGuide $sheet $startRow
    }

    $InstructionSheet.Range($InstructionSheet.Cells.Item(1, 1), $InstructionSheet.Cells.Item($row, 6)).VerticalAlignment = -4160
    $InstructionSheet.Range($InstructionSheet.Cells.Item(1, 1), $InstructionSheet.Cells.Item($row, 6)).Borders.LineStyle = 1
    $InstructionSheet.Range($InstructionSheet.Cells.Item(1, 1), $InstructionSheet.Cells.Item($row, 6)).Borders.Color = 14277081
    $InstructionSheet.Rows.AutoFit()
    foreach ($formulaRow in $script:FormulaImageRows) {
        $InstructionSheet.Rows.Item($formulaRow.Row).RowHeight = $formulaRow.Height
    }
    try {
        # Методические разделы и справка по Results свернуты по умолчанию.
        # Раздел с описанием настроек Config оставляем раскрытым: именно туда
        # ведут ссылки "Подробнее" с листа Config.
        $InstructionSheet.Outline.ShowLevels(1, [Type]::Missing)
    }
    catch {
        try { $InstructionSheet.Outline.ShowLevels(1) } catch {}
    }
    if ($configSettingsBodyEndRow -ge $configSettingsBodyStartRow) {
        try {
            $InstructionSheet.Range($InstructionSheet.Cells.Item($configSettingsBodyStartRow, 1), $InstructionSheet.Cells.Item($configSettingsBodyEndRow, 1)).EntireRow.Hidden = $false
            if ($configSettingsBodyStartRow -gt 1) {
                try { $InstructionSheet.Rows.Item($configSettingsBodyStartRow - 1).ShowDetail = $true } catch {}
            }
        }
        catch {
            # Если Excel не дал раскрыть последнюю группу, ссылки "Подробнее"
            # все равно смогут раскрыть нужную строку через обработчик клика.
        }
    }
    try { $InstructionSheet.Columns.Hidden = $false } catch {}

    $used = $ConfigSheet.UsedRange
    $ConfigSheet.Cells.Item(3, 5).Value2 = "Справка"
    $ConfigSheet.Cells.Item(3, 5).Font.Bold = $true
    $ConfigSheet.Cells.Item(3, 5).Interior.Color = 14277081
    $ConfigSheet.Columns.Item(5).ColumnWidth = 11
    for ($r = 4; $r -le ($used.Row + $used.Rows.Count + 5); $r++) {
        $key = [string]$ConfigSheet.Cells.Item($r, 1).Value2
        if ($anchors.ContainsKey($key)) {
            Add-InstructionHyperlink $ConfigSheet.Cells.Item($r, 5) $InstructionSheet.Name $anchors[$key]
        }
    }
    Add-NamedRangeInstructionLinks $ConfigSheet $InstructionSheet.Name $anchors "rngSteelMaterialParameters" 1 6
    Add-NamedRangeInstructionLinks $ConfigSheet $InstructionSheet.Name $anchors "rngConcreteMaterialParameters" 1 6
    Add-NamedRangeInstructionLinks $ConfigSheet $InstructionSheet.Name $anchors "rngPlotAnnotationSettings" 1 6

    $headerLinks = @{
        "Единицы измерения" = "Units"
        "Система знаков" = "SignConvention"
        "Сочетания нагрузок" = "LoadCombinations"
        "Нагрузки для устойчивости" = "StabilityLoads"
        "СП 35.13330.2011, таблица 7.21" = "SP35Table721"
        "Параметры бетона" = "ConcreteMaterialParameters"
        "Параметры арматуры" = "SteelMaterialParameters"
        "Материал бетона" = "ConcreteMaterialParameters"
        "Материал арматуры" = "SteelMaterialParameters"
        "Настройка расчетных профилей" = "CalculationProfiles"
        "Контрольные точки диаграмм" = "MaterialDiagramControlTables"
        "Аннотации схемы" = "PlotAnnotationSettings"
        "Круглое сечение" = "CircleGeometry"
        "Скругленный прямоугольник" = "RoundedRectangleGeometry"
        "Пустотелый скругленный прямоугольник" = "HollowRectangleGeometry"
        "Сечение из прямоугольников" = "RectSetGeometry"
    }
    for ($r = 1; $r -le ($used.Row + $used.Rows.Count + 40); $r++) {
        for ($c = 1; $c -le 40; $c++) {
            $caption = [string]$ConfigSheet.Cells.Item($r, $c).Value2
            # При обновлении готовой книги заголовок уже содержит пометку ссылки.
            # Сравниваем исходное название, чтобы назначить новый адрес справки
            # и не накапливать повторные "(Подробнее)" при следующем обновлении.
            if ($caption.EndsWith(" (Подробнее)")) {
                $caption = $caption.Substring(0, $caption.Length - " (Подробнее)".Length)
            }
            if ($headerLinks.ContainsKey($caption)) {
                $targetKey = $headerLinks[$caption]
                if ($anchors.ContainsKey($targetKey)) {
                    Add-HeaderInstructionHyperlink $ConfigSheet.Cells.Item($r, $c) $caption $InstructionSheet.Name $anchors[$targetKey]
                }
            }
        }
    }
}

# Рисует таблицу сочетаний нагрузок на Config и сразу назначает ей имя
# rngLoadCombinations. Расчетный код ниже по цепочке не знает, на каком
# листе находится таблица: reader всегда работает через это имя.
function Add-LoadCombinationsTable {
    param(
        [object]$Workbook,
        [object]$Sheet,
        [int]$HeaderRow,
        [int]$StartColumn
    )

    $titleRow = $HeaderRow - 1
    $Sheet.Cells.Item($titleRow, $StartColumn).Value2 = "Сочетания нагрузок"
    $Sheet.Range($Sheet.Cells.Item($titleRow, $StartColumn), $Sheet.Cells.Item($titleRow, $StartColumn + 6)).Merge() | Out-Null
    $Sheet.Cells.Item($titleRow, $StartColumn).Font.Bold = $true
    $Sheet.Cells.Item($titleRow, $StartColumn).Interior.Color = 15921906

    $loadHeaders = @("CombinationID", "N", "Mx", "My", "ProfileId", "CapacityLoadPath", "Comment")
    for ($i = 0; $i -lt $loadHeaders.Count; $i++) {
        $cell = $Sheet.Cells.Item($HeaderRow, $StartColumn + $i)
        $cell.Value2 = $loadHeaders[$i]
        $cell.Font.Bold = $true
        $cell.Interior.Color = $script:ConfigTableHeaderColor
    }
    $Sheet.Cells.Item($HeaderRow, $StartColumn + 1).Formula = "=`"N, `"&INDEX(rngUnitSettings,MATCH(`"Force`",INDEX(rngUnitSettings,,1),0),2)"
    $Sheet.Cells.Item($HeaderRow, $StartColumn + 2).Formula = "=`"Mx, `"&INDEX(rngUnitSettings,MATCH(`"Moment`",INDEX(rngUnitSettings,,1),0),2)"
    $Sheet.Cells.Item($HeaderRow, $StartColumn + 3).Formula = "=`"My, `"&INDEX(rngUnitSettings,MATCH(`"Moment`",INDEX(rngUnitSettings,,1),0),2)"

    $loadRange = $Sheet.Range($Sheet.Cells.Item($HeaderRow, $StartColumn), $Sheet.Cells.Item($HeaderRow + 30, $StartColumn + 6))
    $loadRange.Borders.LineStyle = 1
    $loadRange.Borders.Weight = 2
    $loadRange.Borders.Color = 12632256

    $capacityLoadPathListColumn = 143
    $defaultProfileRow = Get-CalculationProfilesCatalog | Where-Object { $_.Key -eq "Profile.DisplayName" } | Select-Object -First 1
    $defaultProfileName = $defaultProfileRow.PR1
    $Sheet.Cells.Item($HeaderRow + 1, $StartColumn + 4).Value2 = $defaultProfileName

    $lambda = [char]0x03BB
    $capacityLoadPathOptions = @("Auto", "$lambda*Mx", "$lambda*My", "$lambda*Mxy", "$lambda*N", "$lambda*NMxy")
    for ($i = 0; $i -lt $capacityLoadPathOptions.Count; $i++) {
        $Sheet.Cells.Item($i + 1, $capacityLoadPathListColumn).Value2 = $capacityLoadPathOptions[$i]
    }
    $Sheet.Columns.Item($capacityLoadPathListColumn).Hidden = $true
    $capacityLoadPathColName = ConvertTo-ExcelColumn $capacityLoadPathListColumn
    $capacityLoadPathListAddress = "=$" + $capacityLoadPathColName + '$1:$' + $capacityLoadPathColName + '$' + $capacityLoadPathOptions.Count
    $capacityLoadPathRange = $Sheet.Range($Sheet.Cells.Item($HeaderRow + 1, $StartColumn + 5), $Sheet.Cells.Item($HeaderRow + 30, $StartColumn + 5))
    $capacityLoadPathRange.Validation.Delete()
    $capacityLoadPathRange.Validation.Add(3, 1, 1, $capacityLoadPathListAddress)
    $capacityLoadPathRange.Validation.IgnoreBlank = $true
    $capacityLoadPathRange.Validation.InCellDropdown = $true

    Set-WorkbookNameByBounds $Workbook "rngLoadCombinations" $Sheet $HeaderRow $StartColumn ($HeaderRow + 30) ($StartColumn + 6)
}

# Подключает выпадающий список профилей после создания rngCalculationProfiles.
# Ячейки сочетаний остаются обычным пользовательским вводом без формул; динамика
# сидит только в служебном списке, который ссылается на строку Profile.DisplayName.
function Add-LoadProfileValidation {
    param([object]$Workbook, [object]$Sheet, [int]$ListColumn)

    $loadRange = $Workbook.Names.Item("rngLoadCombinations").RefersToRange
    $profilesRange = $Workbook.Names.Item("rngCalculationProfiles").RefersToRange

    $displayRow = 0
    for ($r = 1; $r -le $profilesRange.Rows.Count; $r++) {
        if ([string]$profilesRange.Cells.Item($r, 2).Value2 -eq "Profile.DisplayName") {
            $displayRow = $r
            break
        }
    }
    if ($displayRow -eq 0) { return }

    $profileCount = [Math]::Max(0, $profilesRange.Columns.Count - 3)
    if ($profileCount -le 0) { return }

    for ($i = 0; $i -lt $profileCount; $i++) {
        $sourceCell = $profilesRange.Cells.Item($displayRow, 3 + $i)
        $Sheet.Cells.Item($i + 1, $ListColumn).Formula = "=" + $sourceCell.Address($true, $true)
    }
    $Sheet.Columns.Item($ListColumn).Hidden = $true

    $colName = ConvertTo-ExcelColumn $ListColumn
    $listAddress = "=$" + $colName + '$1:$' + $colName + '$' + $profileCount
    $profileInputRange = $Sheet.Range($loadRange.Cells.Item(2, 5), $loadRange.Cells.Item($loadRange.Rows.Count, 5))
    $profileInputRange.Validation.Delete()
    $profileInputRange.Validation.Add(3, 1, 1, $listAddress)
    $profileInputRange.Validation.IgnoreBlank = $false
    $profileInputRange.Validation.InCellDropdown = $true
}

# Рисует таблицу постоянных/длительных нагрузок для расчета устойчивости.
# Она связана с основной таблицей только через CombinationID: Excel-слой
# прочитает значения, переведет единицы и передаст массив в batch.
function Add-StabilityDurationLoadsTable {
    param(
        [object]$Workbook,
        [object]$Sheet,
        [int]$HeaderRow,
        [int]$StartColumn
    )

    $titleRow = $HeaderRow - 1
    $Sheet.Cells.Item($titleRow, $StartColumn).Value2 = "Нагрузки для устойчивости"
    $Sheet.Range($Sheet.Cells.Item($titleRow, $StartColumn), $Sheet.Cells.Item($titleRow, $StartColumn + 3)).Merge() | Out-Null
    $Sheet.Cells.Item($titleRow, $StartColumn).Font.Bold = $true
    $Sheet.Cells.Item($titleRow, $StartColumn).Interior.Color = 15921906

    $headers = @("LC", "N", "Mx", "My")
    for ($i = 0; $i -lt $headers.Count; $i++) {
        $cell = $Sheet.Cells.Item($HeaderRow, $StartColumn + $i)
        $cell.Value2 = $headers[$i]
        $cell.Font.Bold = $true
        $cell.Interior.Color = $script:ConfigTableHeaderColor
    }
    $Sheet.Cells.Item($HeaderRow, $StartColumn + 1).Formula = "=`"N, `"&INDEX(rngUnitSettings,MATCH(`"Force`",INDEX(rngUnitSettings,,1),0),2)"
    $Sheet.Cells.Item($HeaderRow, $StartColumn + 2).Formula = "=`"Mx, `"&INDEX(rngUnitSettings,MATCH(`"Moment`",INDEX(rngUnitSettings,,1),0),2)"
    $Sheet.Cells.Item($HeaderRow, $StartColumn + 3).Formula = "=`"My, `"&INDEX(rngUnitSettings,MATCH(`"Moment`",INDEX(rngUnitSettings,,1),0),2)"

    for ($r = 1; $r -le 30; $r++) {
        $Sheet.Cells.Item($HeaderRow + $r, $StartColumn).Formula = '=IF(INDEX(rngLoadCombinations,' + ($r + 1) + ',1)="","",INDEX(rngLoadCombinations,' + ($r + 1) + ',1))'
        $Sheet.Cells.Item($HeaderRow + $r, $StartColumn + 1).Value2 = 0
        $Sheet.Cells.Item($HeaderRow + $r, $StartColumn + 2).Value2 = 0
        $Sheet.Cells.Item($HeaderRow + $r, $StartColumn + 3).Value2 = 0
    }

    Set-WorkbookNameByBounds $Workbook "rngStabilityDurationLoads" $Sheet $HeaderRow $StartColumn ($HeaderRow + 30) ($StartColumn + 3)
}

